// 获取设备列表
export async function fetchDevices(filters?: DeviceFilters): Promise<Device[]> {
  try {
    let endpoint = '/devices'
    const params = new URLSearchParams()

    // 添加过滤参数
    if (filters) {
      if (filters.status) params.append('status', filters.status)
      if (filters.device_type) params.append('device_type', filters.device_type)
      if (filters.location) params.append('location', filters.location)
      if (filters.search) params.append('search', filters.search)
      if (filters.page) params.append('page', filters.page.toString())
      if (filters.page_size) params.append('page_size', filters.page_size.toString())
    }

    if (params.toString()) {
      endpoint += `?${params.toString()}`
    }

    const response = await api.get<any>(endpoint)

    // 兼容多种响应格式
    let deviceData: any

    if (Array.isArray(response)) {
      // 后端直接返回数组
      deviceData = response
    } else if (response && response.data) {
      // 包装对象格式：{success: true, data: {...}}
      deviceData = response.data
    } else if (response && response.devices) {
      // 直接设备数组格式：{devices: [...]}
      deviceData = response.devices
    } else {
      // 其他情况返回空数组
      console.warn('Unexpected API response format:', response)
      deviceData = []
    }

    return transformDevicesData(deviceData)

  } catch (error) {
    console.error('获取设备列表失败:', error)
    throw error
  }
}

// 获取单个设备详情
export async function fetchDevice(id: number): Promise<Device | null> {
  try {
    const response = await api.get<ApiResponse<Device>>(`/devices/${id}`)

    if (response.success && response.data) {
      return transformDeviceData(response.data)
    } else {
      throw new Error(response.message || '获取设备详情失败')
    }
  } catch (error) {
    console.error('获取设备详情失败:', error)
    return null
  }
}

// 创建设备
export async function createDevice(device: Omit<Device, 'id' | 'created_at' | 'updated_at'>): Promise<Device> {
  try {
