// 批量操作
export async function bulkDeviceAction(action: BulkActionType, params?: any): Promise<BulkOperationResult> {
  try {
    const response = await api.post<ApiResponse<{ processed_count: number; failed_count: number; errors: any[] }>>('/devices/bulk-action', {
      action,
      ...params
    })

    if (response.success) {
      return {
        success: true,
        processed_count: response.data?.processed_count || 0,
        failed_count: response.data?.failed_count || 0,
        errors: response.data?.errors || [],
        message: response.message || '批量操作成功'
      }
    } else {
      return {
        success: false,
        processed_count: 0,
        failed_count: 0,
        errors: [{ error: response.message || '批量操作失败' }],
        message: response.message || '批量操作失败'
      }
    }
  } catch (error) {
    console.error('批量操作失败:', error)
    return {
      success: false,
      processed_count: 0,
      failed_count: 0,
      errors: [{ error: error instanceof Error ? error.message : '批量操作失败' }],
      message: '批量操作失败'
    }
  }
}

