    const response = await api.post<ApiResponse<{ imported_count: number; skipped_count: number; errors: any[] }>>('/devices/bulk-import', {
      devices,
      auto_detect: true,
      skip_duplicates: true
    })

    if (response.success && response.data) {
      return {
        success: true,
        imported_count: response.data.imported_count || 0,
        skipped_count: response.data.skipped_count || 0,
        errors: response.data.errors || [],
        message: response.message || '设备导入成功'
      }
    } else {
      return {
        success: false,
        imported_count: 0,
        skipped_count: 0,
        errors: [{ row: 0, data: devices[0], error: response.message || '导入失败' }],
        message: response.message || '设备导入失败'
      }
    }
  } catch (error) {
    console.error('设备导入失败:', error)
    return {
      success: false,
      imported_count: 0,
      skipped_count: 0,
      errors: [{ row: 0, data: devices[0], error: error instanceof Error ? error.message : '导入失败' }],
