// 数据转换函数
function transformDevicesData(apiData: any): Device[] {
  if (!Array.isArray(apiData)) {
    return Array.isArray(apiData.devices) ? apiData.devices.map(transformDeviceData) : []
  }
  return apiData.map(transformDeviceData)
}

function transformDeviceData(apiData: any): Device {
  return {
    id: apiData.id,
    name: apiData.name,
    ip: apiData.ip,
    device_type: apiData.device_type,
    status: apiData.status || 'unknown',
    location: apiData.location || '',
    last_seen: apiData.last_seen || '',
    uptime: apiData.uptime || '0天 0小时',
    cpu_usage: apiData.cpu_usage || 0,
    memory_usage: apiData.memory_usage || 0,
    network_traffic: apiData.network_traffic || 0,
    alert_count: apiData.alert_count || 0,
    description: apiData.description || '',
    snmp_community: apiData.snmp_community || '',
    ssh_username: apiData.ssh_username || '',
    ssh_password: apiData.ssh_password || '',
    created_at: apiData.created_at || new Date().toISOString(),
    updated_at: apiData.updated_at || new Date().toISOString(),
  }
}

