import React, { useState, useCallback } from 'react'
import { Upload, Download, FileText, AlertCircle, CheckCircle, X, Plus } from 'lucide-react'
import {
  Modal,
  Button,
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  Input,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Badge,
  Loading
} from '@/components/atoms'
import { DeviceImportData, ImportResult, DeviceType } from '../types'

interface BulkDeviceImportProps {
  isOpen: boolean
  onClose: () => void
  onImport: (devices: DeviceImportData[]) => Promise<ImportResult>
}

interface ParsedCSVData {
  headers: string[]
  rows: string[][]
  mappedData: DeviceImportData[]
}

export const BulkDeviceImport: React.FC<BulkDeviceImportProps> = ({
  isOpen,
  onClose,
  onImport
}) => {
  const [currentStep, setCurrentStep] = useState<'upload' | 'mapping' | 'preview' | 'result'>('upload')
  const [csvData, setCsvData] = useState<ParsedCSVData | null>(null)
  const [fieldMapping, setFieldMapping] = useState<Record<string, string>>({})
  const [isProcessing, setIsProcessing] = useState(false)
  const [importResult, setImportResult] = useState<ImportResult | null>(null)
  const [manualDevices, setManualDevices] = useState<DeviceImportData[]>([
    {
      name: '',
      ip: '',
      device_type: 'switch',
      location: '',
      description: ''
    }
  ])

  const requiredFields = [
    { key: 'name', label: '设备名称', required: true },
    { key: 'ip', label: 'IP地址', required: true },
    { key: 'device_type', label: '设备类型', required: true },
    { key: 'location', label: '位置', required: false },
    { key: 'description', label: '描述', required: false },
    { key: 'snmp_community', label: 'SNMP团体名', required: false },
    { key: 'ssh_username', label: 'SSH用户名', required: false },
    { key: 'ssh_password', label: 'SSH密码', required: false }
  ]

  const deviceTypes: Array<{ value: DeviceType; label: string }> = [
    { value: 'switch', label: '交换机' },
    { value: 'router', label: '路由器' },
    { value: 'firewall', label: '防火墙' },
    { value: 'wireless_ap', label: '无线AP' }
  ]

  // CSV文件解析
  const parseCSV = (content: string): ParsedCSVData => {
    const lines = content.trim().split('\n')
    const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''))
    const rows = lines.slice(1).map(line => 
      line.split(',').map(cell => cell.trim().replace(/"/g, ''))
    )

    return {
      headers,
      rows,
      mappedData: []
    }
  }

  // 文件上传处理
  const handleFileUpload = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string
        const parsed = parseCSV(content)
        setCsvData(parsed)
        setCurrentStep('mapping')
      } catch (error) {
        console.error('CSV解析失败:', error)
      }
    }
    reader.readAsText(file, 'UTF-8')
  }, [])

  // 字段映射处理
  const handleMappingComplete = () => {
    if (!csvData) return

    const mappedData: DeviceImportData[] = csvData.rows.map(row => {
      const device: any = {}
      Object.entries(fieldMapping).forEach(([csvField, deviceField]) => {
        const columnIndex = csvData.headers.indexOf(csvField)
        if (columnIndex !== -1 && deviceField) {
          device[deviceField] = row[columnIndex] || ''
        }
      })
      return device as DeviceImportData
    })

    setCsvData({ ...csvData, mappedData })
    setCurrentStep('preview')
  }

  // 手动添加设备
  const handleManualDeviceChange = (index: number, field: keyof DeviceImportData, value: string) => {
    const updated = [...manualDevices]
    updated[index] = { ...updated[index], [field]: value }
    setManualDevices(updated)
  }

  const addManualDevice = () => {
    setManualDevices([...manualDevices, {
      name: '',
      ip: '',
      device_type: 'switch',
      location: '',
      description: ''
    }])
  }

  const removeManualDevice = (index: number) => {
    if (manualDevices.length > 1) {
      setManualDevices(manualDevices.filter((_, i) => i !== index))
    }
  }

  // 执行导入
  const handleImport = async () => {
    setIsProcessing(true)
    try {
      const devicesToImport = csvData?.mappedData || manualDevices.filter(d => d.name && d.ip)
      const result = await onImport(devicesToImport)
      setImportResult(result)
      setCurrentStep('result')
    } catch (error) {
      console.error('导入失败:', error)
    } finally {
      setIsProcessing(false)
    }
  }

  // 下载模板
  const downloadTemplate = () => {
    const csvContent = [
      '设备名称,IP地址,设备类型,位置,描述,SNMP团体名,SSH用户名,SSH密码',
      '核心交换机-01,192.168.1.1,switch,数据中心A,核心网络设备,public,admin,',
      '路由器网关-01,192.168.1.254,router,数据中心A,主网关路由器,public,admin,',
      '防火墙-01,192.168.1.100,firewall,数据中心B,边界防火墙,public,admin,'
    ].join('\n')

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = '设备导入模板.csv'
    link.click()
  }

  const renderUploadStep = () => (
    <div className="space-y-6">
      <div className="text-center">
        <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-blue-100 flex items-center justify-center">
          <Upload className="h-8 w-8 text-blue-600" />
        </div>
        <h3 className="text-lg font-semibold text-gray-900 mb-2">批量导入设备</h3>
        <p className="text-sm text-gray-600">
          支持CSV文件导入或手动添加设备
        </p>
      </div>

      {/* CSV导入 */}
      <Card>
        <CardHeader>
          <CardTitle className="text-sm">CSV文件导入</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="flex items-center gap-3">
              <Button
                variant="outline"
                onClick={downloadTemplate}
                className="flex items-center gap-2"
              >
                <Download className="h-4 w-4" />
                下载模板
              </Button>
              <span className="text-sm text-gray-500">建议先下载模板文件</span>
            </div>

            <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center">
              <input
                type="file"
                accept=".csv"
                onChange={handleFileUpload}
                className="hidden"
                id="csv-upload"
              />
              <label htmlFor="csv-upload" className="cursor-pointer">
                <FileText className="h-12 w-12 text-gray-400 mx-auto mb-2" />
                <p className="text-sm font-medium text-gray-900 mb-1">
                  点击选择CSV文件
                </p>
                <p className="text-sm text-gray-500">
                  或将文件拖拽到此处
                </p>
              </label>
            </div>
          </div>
        </CardContent>
      </Card>

      <div className="text-center text-gray-500">或</div>

      {/* 手动添加 */}
      <Card>
        <CardHeader>
          <CardTitle className="text-sm">手动添加设备</CardTitle>
        </CardHeader>
        <CardContent>
          <Button
            onClick={() => setCurrentStep('preview')}
            className="w-full"
          >
            <Plus className="h-4 w-4 mr-2" />
            手动添加设备
          </Button>
        </CardContent>
      </Card>
    </div>
  )

  const renderMappingStep = () => (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-gray-900 mb-2">字段映射</h3>
        <p className="text-sm text-gray-600">
          请将CSV文件的列映射到相应的设备字段
        </p>
      </div>

      <Card>
        <CardContent className="p-4">
          <div className="space-y-4">
            {requiredFields.map(field => (
              <div key={field.key} className="grid grid-cols-2 gap-4 items-center">
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium text-gray-900">
                    {field.label}
                  </span>
                  {field.required && (
                    <span className="text-red-500 text-xs">*</span>
                  )}
                </div>
                <Select
                  value={fieldMapping[field.key] || ''}
                  onValueChange={(value) => 
                    setFieldMapping(prev => ({ ...prev, [field.key]: value }))
                  }
                >
                  <SelectTrigger>
                    <SelectValue placeholder="选择CSV列" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">不映射</SelectItem>
                    {csvData?.headers.map(header => (
                      <SelectItem key={header} value={header}>
                        {header}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      <div className="flex justify-end gap-3">
        <Button
          variant="outline"
          onClick={() => setCurrentStep('upload')}
        >
          上一步
        </Button>
        <Button
          onClick={handleMappingComplete}
          disabled={!fieldMapping.name || !fieldMapping.ip || !fieldMapping.device_type}
        >
          下一步
        </Button>
      </div>
    </div>
  )

  const renderPreviewStep = () => {
    const devicesToShow = csvData?.mappedData || manualDevices

    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-lg font-semibold text-gray-900 mb-2">预览导入数据</h3>
            <p className="text-sm text-gray-600">
              确认以下设备信息无误后开始导入
            </p>
          </div>
          {!csvData && (
            <Button
              variant="outline"
              onClick={addManualDevice}
              size="sm"
            >
              <Plus className="h-4 w-4 mr-2" />
              添加设备
            </Button>
          )}
        </div>

        <Card>
          <CardContent className="p-4">
            <div className="space-y-4 max-h-96 overflow-y-auto">
              {!csvData && (
                <>
                  {manualDevices.map((device, index) => (
                    <div key={index} className="grid grid-cols-12 gap-2 items-center p-3 border rounded-lg">
                      <div className="col-span-2">
                        <Input
                          placeholder="设备名称 *"
                          value={device.name}
                          onChange={(e) => handleManualDeviceChange(index, 'name', e.target.value)}
                        />
                      </div>
                      <div className="col-span-2">
                        <Input
                          placeholder="IP地址 *"
                          value={device.ip}
                          onChange={(e) => handleManualDeviceChange(index, 'ip', e.target.value)}
                        />
                      </div>
                      <div className="col-span-2">
                        <Select
                          value={device.device_type}
                          onValueChange={(value: DeviceType) =>
                            handleManualDeviceChange(index, 'device_type', value)
                          }
                        >
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {deviceTypes.map(type => (
                              <SelectItem key={type.value} value={type.value}>
                                {type.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="col-span-2">
                        <Input
                          placeholder="位置"
                          value={device.location || ''}
                          onChange={(e) => handleManualDeviceChange(index, 'location', e.target.value)}
                        />
                      </div>
                      <div className="col-span-3">
                        <Input
                          placeholder="描述"
                          value={device.description || ''}
                          onChange={(e) => handleManualDeviceChange(index, 'description', e.target.value)}
                        />
                      </div>
                      <div className="col-span-1 flex justify-end">
                        {manualDevices.length > 1 && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => removeManualDevice(index)}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        )}
                      </div>
                    </div>
                  ))}
                </>
              )}

              {csvData && csvData.mappedData.map((device, index) => (
                <div key={index} className="p-3 border rounded-lg">
                  <div className="grid grid-cols-4 gap-4 text-sm">
                    <div>
                      <span className="font-medium text-gray-900">{device.name}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">{device.ip}</span>
                    </div>
                    <div>
                      <Badge variant="outline">{device.device_type}</Badge>
                    </div>
                    <div>
                      <span className="text-gray-600">{device.location}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        <div className="flex justify-between">
          <Button
            variant="outline"
            onClick={() => csvData ? setCurrentStep('mapping') : setCurrentStep('upload')}
          >
            上一步
          </Button>
          <Button
            onClick={handleImport}
            disabled={isProcessing || devicesToShow.filter(d => d.name && d.ip).length === 0}
          >
            {isProcessing ? (
              <>
                <Loading size="sm" className="mr-2" />
                导入中...
              </>
            ) : (
              <>导入设备 ({devicesToShow.filter(d => d.name && d.ip).length})</>
            )}
          </Button>
        </div>
      </div>
    )
  }

  const renderResultStep = () => {
    if (!importResult) return null

    return (
      <div className="space-y-6">
        <div className="text-center">
          <div className={`w-16 h-16 mx-auto mb-4 rounded-full flex items-center justify-center ${
            importResult.success ? 'bg-green-100' : 'bg-red-100'
          }`}>
            {importResult.success ? (
              <CheckCircle className="h-8 w-8 text-green-600" />
            ) : (
              <AlertCircle className="h-8 w-8 text-red-600" />
            )}
          </div>
          <h3 className="text-lg font-semibold text-gray-900 mb-2">
            {importResult.success ? '导入完成' : '导入失败'}
          </h3>
          <p className="text-sm text-gray-600">
            {importResult.message}
          </p>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <Card>
            <CardContent className="p-4">
              <div className="text-center">
                <div className="text-2xl font-bold text-green-600">
                  {importResult.imported_count}
                </div>
                <div className="text-sm text-gray-600">成功导入</div>
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-4">
              <div className="text-center">
                <div className="text-2xl font-bold text-red-600">
                  {importResult.skipped_count}
                </div>
                <div className="text-sm text-gray-600">跳过/失败</div>
              </div>
            </CardContent>
          </Card>
        </div>

        {importResult.errors.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle className="text-sm text-red-800">错误详情</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="max-h-48 overflow-y-auto space-y-2">
                {importResult.errors.map((error, index) => (
                  <div key={index} className="text-sm text-red-700 p-2 bg-red-50 rounded">
                    第 {error.row} 行: {error.error}
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        <div className="flex justify-center">
          <Button onClick={onClose}>
            完成
          </Button>
        </div>
      </div>
    )
  }

  const steps = [
    { key: 'upload', title: '选择导入方式' },
    { key: 'mapping', title: '字段映射' },
    { key: 'preview', title: '预览数据' },
    { key: 'result', title: '导入结果' }
  ]

  return (
    <Modal open={isOpen} onOpenChange={onClose}>
      <div className="p-6">
        {/* 步骤指示器 */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            {steps.map((step, index) => {
              const isActive = step.key === currentStep
              const isCompleted = steps.findIndex(s => s.key === currentStep) > index

              return (
                <React.Fragment key={step.key}>
                  <div className="flex items-center">
                    <div className={`
                      w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium
                      ${isActive ? 'bg-blue-600 text-white' : ''}
                      ${isCompleted ? 'bg-green-600 text-white' : ''}
                      ${!isActive && !isCompleted ? 'bg-gray-200 text-gray-600' : ''}
                    `}>
                      {isCompleted ? <CheckCircle className="h-4 w-4" /> : index + 1}
                    </div>
                    <span className="ml-2 text-sm font-medium text-gray-900">
                      {step.title}
                    </span>
                  </div>
                  {index < steps.length - 1 && (
                    <div className="flex-1 mx-4">
                      <div className={`h-1 rounded ${
                        isCompleted ? 'bg-green-600' : 'bg-gray-200'
                      }`} />
                    </div>
                  )}
                </React.Fragment>
              )
            })}
          </div>
        </div>

        {/* 步骤内容 */}
        <div className="min-h-[400px]">
          {currentStep === 'upload' && renderUploadStep()}
          {currentStep === 'mapping' && renderMappingStep()}
          {currentStep === 'preview' && renderPreviewStep()}
          {currentStep === 'result' && renderResultStep()}
        </div>
      </div>
    </Modal>
  )
}

import React, { useState } from 'react'
import { Settings, Save, AlertCircle } from 'lucide-react'
import {
  Modal,
  Button,
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  Input,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Badge,
  Loading
} from '@/components/atoms'
import { Device, DeviceType, DeviceStatus } from '../types'

interface BulkDeviceUpdateProps {
  isOpen: boolean
  onClose: () => void
  selectedDevices: Device[]
  onBulkUpdate: (updates: Partial<Device>) => Promise<void>
  isProcessing: boolean
}

interface UpdateField {
  key: keyof Device
  label: string
  type: 'text' | 'select' | 'textarea'
  options?: Array<{ value: string; label: string }>
  description?: string
}

export const BulkDeviceUpdate: React.FC<BulkDeviceUpdateProps> = ({
  isOpen,
  onClose,
  selectedDevices,
  onBulkUpdate,
  isProcessing
}) => {
  const [selectedFields, setSelectedFields] = useState<Set<keyof Device>>(new Set())
  const [updateValues, setUpdateValues] = useState<Partial<Device>>({})

  const updateFields: UpdateField[] = [
    {
      key: 'device_type',
      label: '设备类型',
      type: 'select',
      options: [
        { value: 'switch', label: '交换机' },
        { value: 'router', label: '路由器' },
        { value: 'firewall', label: '防火墙' },
        { value: 'wireless_ap', label: '无线AP' }
      ],
      description: '更改设备的类型分类'
    },
    {
      key: 'status',
      label: '设备状态',
      type: 'select',
      options: [
        { value: 'online', label: '在线' },
        { value: 'offline', label: '离线' },
        { value: 'warning', label: '告警' },
        { value: 'maintenance', label: '维护' }
      ],
      description: '手动设置设备状态'
    },
    {
      key: 'location',
      label: '设备位置',
      type: 'text',
      description: '批量更新设备的物理位置'
    }
  ]

  const handleFieldToggle = (fieldKey: keyof Device) => {
    const newSelectedFields = new Set(selectedFields)
    if (newSelectedFields.has(fieldKey)) {
      newSelectedFields.delete(fieldKey)
      const newValues = { ...updateValues }
      delete newValues[fieldKey]
      setUpdateValues(newValues)
    } else {
      newSelectedFields.add(fieldKey)
    }
    setSelectedFields(newSelectedFields)
  }

  const handleValueChange = (fieldKey: keyof Device, value: any) => {
    setUpdateValues(prev => ({
      ...prev,
      [fieldKey]: value
    }))
  }

  const handleSubmit = async () => {
    if (selectedFields.size === 0) return

    const updates: Partial<Device> = {}
    selectedFields.forEach(field => {
      const value = updateValues[field]
      if (value !== undefined && value !== '') {
        // 确保类型正确转换
        if (field === 'device_type' || field === 'status' || field === 'location') {
          ;(updates as any)[field] = value
        }
      }
    })

    await onBulkUpdate(updates)
  }

  const renderFieldInput = (field: UpdateField) => {
    if (!selectedFields.has(field.key)) return null

    switch (field.type) {
      case 'select':
        return (
          <Select
            value={updateValues[field.key] as string || ''}
            onValueChange={(value) => handleValueChange(field.key, value)}
          >
            <SelectTrigger>
              <SelectValue placeholder={`选择${field.label}`} />
            </SelectTrigger>
            <SelectContent>
              {field.options?.map(option => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )

      case 'textarea':
        return (
          <textarea
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 resize-none"
            rows={3}
            placeholder={`输入${field.label}`}
            value={updateValues[field.key] as string || ''}
            onChange={(e) => handleValueChange(field.key, e.target.value)}
          />
        )

      default:
        return (
          <Input
            type="text"
            placeholder={`输入${field.label}`}
            value={updateValues[field.key] as string || ''}
            onChange={(e) => handleValueChange(field.key, e.target.value)}
          />
        )
    }
  }

  return (
    <Modal open={isOpen} onOpenChange={onClose}>
      <div className="p-6">
        {/* 标题 */}
        <div className="flex items-center gap-3 mb-6">
          <div className="flex-shrink-0 w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center">
            <Settings className="h-5 w-5 text-blue-600" />
          </div>
          <div>
            <h2 className="text-xl font-semibold text-gray-900">批量更新设备</h2>
            <p className="text-sm text-gray-600 mt-1">
              将更新 {selectedDevices.length} 个设备的属性
            </p>
          </div>
        </div>

        {/* 选中设备概览 */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle className="text-sm">选中的设备</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="max-h-32 overflow-y-auto">
              <div className="flex flex-wrap gap-2">
                {selectedDevices.slice(0, 10).map((device) => (
                  <Badge key={device.id} variant="outline" className="text-xs">
                    {device.name}
                  </Badge>
                ))}
                {selectedDevices.length > 10 && (
                  <Badge variant="secondary" className="text-xs">
                    +{selectedDevices.length - 10} 更多
                  </Badge>
                )}
              </div>
            </div>
          </CardContent>
        </Card>

        {/* 更新字段选择 */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle className="text-sm">选择要更新的字段</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {updateFields.map((field) => (
                <div key={String(field.key)} className="space-y-2">
                  <div className="flex items-center gap-3">
                    <input
                      type="checkbox"
                      id={`field-${String(field.key)}`}
                      checked={selectedFields.has(field.key)}
                      onChange={() => handleFieldToggle(field.key)}
                      className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                    />
                    <label 
                      htmlFor={`field-${String(field.key)}`}
                      className="font-medium text-gray-900 cursor-pointer"
                    >
                      {field.label}
                    </label>
                  </div>

                  {field.description && (
                    <p className="text-sm text-gray-600 ml-7">
                      {field.description}
                    </p>
                  )}

                  {selectedFields.has(field.key) && (
                    <div className="ml-7">
                      {renderFieldInput(field)}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* 更新预览 */}
        {selectedFields.size > 0 && (
          <Card className="mb-6">
            <CardHeader>
              <CardTitle className="text-sm flex items-center gap-2">
                <AlertCircle className="h-4 w-4" />
                更新预览
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <p className="text-sm text-blue-800 mb-2">
                  将对 {selectedDevices.length} 个设备执行以下更新：
                </p>
                <div className="space-y-1">
                  {Array.from(selectedFields).map(field => {
                    const fieldConfig = updateFields.find(f => f.key === field)
                    const value = updateValues[field]
                    if (!value || !fieldConfig) return null

                    return (
                      <div key={String(field)} className="text-sm text-blue-700">
                        • {fieldConfig.label}: {String(value)}
                      </div>
                    )
                  })}
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        {/* 底部按钮 */}
        <div className="flex items-center justify-end gap-3">
          <Button
            variant="outline"
            onClick={onClose}
            disabled={isProcessing}
          >
            取消
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={isProcessing || selectedFields.size === 0}
            className="min-w-[100px]"
          >
            {isProcessing ? (
              <Loading size="sm" />
            ) : (
              <>
                <Save className="h-4 w-4 mr-2" />
                批量更新
              </>
            )}
          </Button>
        </div>
      </div>
    </Modal>
  )
}

import React, { useState } from 'react'
import { motion } from 'framer-motion'
import {
  Upload,
  FileText,
  Download,
  AlertTriangle,
  CheckCircle,
  X,
  Plus,
  Settings,
  Trash2,
  Users,
  UserX
} from 'lucide-react'
import {
  Button,
  Modal,
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  Badge,
  Input,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Loading
} from '@/components/atoms'
import { Device, BulkActionType, BulkOperationResult, DeviceImportData } from '../types'
import { BulkDeviceImport } from './BulkDeviceImport'
import { BulkDeviceUpdate } from './BulkDeviceUpdate'
import { BulkDeviceDelete } from './BulkDeviceDelete'

interface BulkOperationModalProps {
  isOpen: boolean
  onClose: () => void
  selectedDevices: number[]
  devices: Device[]
  onBulkAction: (action: BulkActionType, params?: any) => Promise<BulkOperationResult>
  onClearSelection: () => void
}

export const BulkOperationModal: React.FC<BulkOperationModalProps> = ({
  isOpen,
  onClose,
  selectedDevices,
  devices,
  onBulkAction,
  onClearSelection
}) => {
  const [activeOperation, setActiveOperation] = useState<string>('')
  const [isProcessing, setIsProcessing] = useState(false)
  const [operationResult, setOperationResult] = useState<BulkOperationResult | null>(null)

  const selectedDeviceData = devices.filter(device => selectedDevices.includes(device.id))

  const handleOperationComplete = (result: BulkOperationResult) => {
    setOperationResult(result)
    setIsProcessing(false)
    if (result.success) {
      setTimeout(() => {
        onClearSelection()
        onClose()
      }, 2000)
    }
  }

  const handleBulkDelete = async () => {
    setIsProcessing(true)
    try {
      const result = await onBulkAction('batch_delete', {
        device_ids: selectedDevices
      })
      handleOperationComplete(result)
    } catch (error) {
      handleOperationComplete({
        success: false,
        processed_count: 0,
        failed_count: selectedDevices.length,
        errors: [{ error: error instanceof Error ? error.message : '删除失败' }],
        message: '批量删除操作失败'
      })
    }
  }

  const handleBulkInspection = async () => {
    setIsProcessing(true)
    try {
      const result = await onBulkAction('start_inspection', {
        device_ids: selectedDevices
      })
      handleOperationComplete(result)
    } catch (error) {
      handleOperationComplete({
        success: false,
        processed_count: 0,
        failed_count: selectedDevices.length,
        errors: [{ error: error instanceof Error ? error.message : '启动巡检失败' }],
        message: '批量巡检操作失败'
      })
    }
  }

  const getBulkOperations = () => [
    {
      id: 'inspect',
      title: '批量巡检',
      description: '对选中设备执行巡检任务',
      icon: CheckCircle,
      variant: 'primary' as const,
      action: handleBulkInspection
    },
    {
      id: 'update',
      title: '批量更新',
      description: '批量修改设备属性',
      icon: Settings,
      variant: 'secondary' as const,
      action: () => setActiveOperation('update')
    },
    {
      id: 'group',
      title: '分组管理',
      description: '批量添加/移除设备分组',
      icon: Users,
      variant: 'secondary' as const,
      action: () => setActiveOperation('group')
    },
    {
      id: 'delete',
      title: '批量删除',
      description: '删除所选设备（不可恢复）',
      icon: Trash2,
      variant: 'destructive' as const,
      action: () => setActiveOperation('delete')
    }
  ]

  if (operationResult) {
    return (
      <Modal open={isOpen} onOpenChange={onClose}>
        <div className="p-6">
          <div className="flex items-center gap-3 mb-4">
            {operationResult.success ? (
              <div className="flex-shrink-0 w-10 h-10 rounded-full bg-green-100 flex items-center justify-center">
                <CheckCircle className="h-6 w-6 text-green-600" />
              </div>
            ) : (
              <div className="flex-shrink-0 w-10 h-10 rounded-full bg-red-100 flex items-center justify-center">
                <AlertTriangle className="h-6 w-6 text-red-600" />
              </div>
            )}
            <div>
              <h3 className="text-lg font-semibold text-gray-900">
                {operationResult.success ? '操作完成' : '操作失败'}
              </h3>
              <p className="text-sm text-gray-600">{operationResult.message}</p>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4 mb-4">
            <Card>
              <CardContent className="p-4">
                <div className="text-center">
                  <div className="text-2xl font-bold text-green-600">
                    {operationResult.processed_count}
                  </div>
                  <div className="text-sm text-gray-600">成功处理</div>
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4">
                <div className="text-center">
                  <div className="text-2xl font-bold text-red-600">
                    {operationResult.failed_count}
                  </div>
                  <div className="text-sm text-gray-600">处理失败</div>
                </div>
              </CardContent>
            </Card>
          </div>

          {operationResult.errors.length > 0 && (
            <div className="mb-4">
              <h4 className="text-sm font-medium text-gray-900 mb-2">错误详情：</h4>
              <div className="max-h-32 overflow-y-auto bg-red-50 rounded-lg p-3">
                {operationResult.errors.map((error, index) => (
                  <div key={index} className="text-sm text-red-700 mb-1">
                    {error.device_name && `设备 ${error.device_name}: `}
                    {error.error}
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="flex justify-end gap-3">
            <Button onClick={onClose}>关闭</Button>
          </div>
        </div>
      </Modal>
    )
  }

  if (activeOperation === 'delete') {
    return (
      <BulkDeviceDelete
        isOpen={isOpen}
        onClose={() => {
          setActiveOperation('')
          onClose()
        }}
        selectedDevices={selectedDeviceData}
        onConfirm={handleBulkDelete}
        isProcessing={isProcessing}
      />
    )
  }

  if (activeOperation === 'update') {
    return (
      <BulkDeviceUpdate
        isOpen={isOpen}
        onClose={() => {
          setActiveOperation('')
          onClose()
        }}
        selectedDevices={selectedDeviceData}
        onBulkUpdate={async (updates) => {
          setIsProcessing(true)
          try {
            const result = await onBulkAction('batch_update', {
              device_ids: selectedDevices,
              updates
            })
            handleOperationComplete(result)
          } catch (error) {
            handleOperationComplete({
              success: false,
              processed_count: 0,
              failed_count: selectedDevices.length,
              errors: [{ error: error instanceof Error ? error.message : '更新失败' }],
              message: '批量更新操作失败'
            })
          }
        }}
        isProcessing={isProcessing}
      />
    )
  }

  return (
    <Modal open={isOpen} onOpenChange={onClose}>
      <div className="p-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="text-xl font-semibold text-gray-900">批量操作</h2>
            <p className="text-sm text-gray-600 mt-1">
              已选择 {selectedDevices.length} 个设备
            </p>
          </div>
          <Button
            variant="ghost"
            size="sm"
