      endpoint += `?time_range=${timeRange}`
    }

    const response = await api.get<InspectionApiResponse<any>>(endpoint)

    if (response.data) {
      return transformStatsData(response.data)
    } else {
      throw new Error('获取统计数据失败')
    }
  } catch (error) {
    console.error('获取统计数据失败:', error)
    return {
      totalStrategies: 0,
      activeStrategies: 0,
      todayExecutions: 0,
      successRate: 0,
      avgScore: 0,
      recentExecutions: []
    }
  }
}

// 获取巡检趋势数据
export async function fetchInspectionTrends(params: {
  period: 'day' | 'week' | 'month'
  startDate?: string
  endDate?: string
}): Promise<Array<{
  date: string
  executions: number
  success: number
  failed: number
  avgScore: number
}>> {
  try {
    let endpoint = '/inspection/trends'
    const searchParams = new URLSearchParams()

    searchParams.append('period', params.period)
    if (params.startDate) searchParams.append('start_date', params.startDate)
    if (params.endDate) searchParams.append('end_date', params.endDate)

    endpoint += `?${searchParams.toString()}`

    const response = await api.get<InspectionApiResponse<any>>(endpoint)

    if (response.data) {
      return response.data || []
    } else {
      throw new Error('获取趋势数据失败')
    }
  } catch (error) {
    console.error('获取趋势数据失败:', error)
    return []
  }
}

