// ==================== 数据转换函数 ====================

function transformTemplateData(apiData: any): InspectionTemplate {
  return {
    id: apiData.id,
    name: apiData.name,
    description: apiData.description || '',
    category: apiData.category || 'custom',
    deviceTypes: apiData.device_types || [],
    checkItems: apiData.check_items || [],
    isBuiltIn: apiData.is_built_in !== false,
    createdAt: apiData.created_at,
    updatedAt: apiData.updated_at,
  }
}

function transformTaskData(apiData: any): InspectionTask {
  return {
    id: apiData.id,
    strategyId: apiData.strategy_id || '',
    deviceId: apiData.device_id || '',
    templateId: apiData.template_id || '',
    status: apiData.status || 'pending',
    progress: apiData.progress || 0,
    startTime: apiData.started_at,
    endTime: apiData.completed_at,
    checkItems: apiData.check_items || [],
    results: apiData.results || []
  }
}

function transformResultData(apiData: any): InspectionResult {
  return {
    id: apiData.id,
    taskId: apiData.task_id,
    executionId: apiData.execution_id || '',
    deviceId: apiData.device_id,
    deviceName: apiData.device_name || '未知设备',
    status: apiData.status || 'offline',
    score: apiData.score || 0,
    totalChecks: apiData.total_checks || 0,
    passedChecks: apiData.passed_checks || 0,
    failedChecks: apiData.failed_checks || 0,
    warningChecks: apiData.warning_checks || 0,
    results: apiData.check_results || [],
    summary: apiData.summary || '',
    createdAt: apiData.created_at || apiData.completed_at || ''
  }
}

function transformExecutionData(apiData: any): InspectionExecution {
  return {
    id: apiData.id,
    strategyId: apiData.strategy_id || '',
    strategyName: apiData.strategy_name || '',
    triggerType: apiData.trigger_type || 'manual',
    triggerUser: apiData.trigger_user,
    status: apiData.status || 'pending',
    progress: apiData.progress || 0,
    totalDevices: apiData.total_devices || 0,
    completedDevices: apiData.completed_devices || 0,
    startTime: apiData.start_time || '',
    endTime: apiData.end_time,
    duration: apiData.duration,
    summary: transformSummaryData(apiData.summary || {})
  }
}

function transformSummaryData(apiData: any): InspectionSummary {
  return {
    totalChecks: apiData.total_checks || 0,
    passedChecks: apiData.passed_checks || 0,
    failedChecks: apiData.failed_checks || 0,
    warningChecks: apiData.warning_checks || 0,
    score: apiData.score || 0,
    deviceResults: (apiData.device_results || []).map(transformDeviceResultData)
  }
}

function transformDeviceResultData(apiData: any): DeviceInspectionResult {
  return {
    deviceId: apiData.device_id,
    deviceName: apiData.device_name || '',
    deviceType: apiData.device_type || '',
    status: apiData.status || 'offline',
    score: apiData.score || 0,
    checkResults: apiData.check_results || [],
    executionTime: apiData.execution_time || 0
  }
}

function transformStatsData(apiData: any): InspectionStats {
  return {
    totalStrategies: apiData.totalStrategies || 0,
    activeStrategies: apiData.activeStrategies || 0,
    todayExecutions: apiData.todayExecutions || 0,
    successRate: apiData.successRate || 0,
    avgScore: apiData.avgScore || 0,
    changes: apiData.changes || {
      executionsChange: "0.0%",
      successRateChange: "0.0%",
      avgScoreChange: "0.0%",
      strategiesChange: "0.0%"
    },
    recentExecutions: (apiData.recentExecutions || []).map(transformExecutionData)
  }
}

