  CardHeader,
  CardTitle,
  CardContent,
  Button,
  Badge,
  Table,
  Column,
  ConfirmModal
} from '@/components/atoms'
import { 
  useInspectionStrategies, 
  useToggleStrategy, 
  useDeleteStrategy,
  useTriggerExecution 
} from '../hooks/useInspection'
import { InspectionStrategy } from '../types'
import { StrategyModal } from './StrategyModal'

interface Props {
  searchText: string
