import React, { useState } from 'react'
import { motion } from 'framer-motion'
import { 
  Plus, 
  Edit, 
  Copy, 
  Trash2, 
  Eye, 
  FileText, 
  Shield, 
  Monitor, 
  Settings,
  AlertCircle
} from 'lucide-react'
import {
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  Button,
  Badge,
  Table,
  Column,
  ConfirmModal
} from '@/components/atoms'
import { 
  useInspectionTemplates, 
  useCloneTemplate 
} from '../hooks/useInspection'
import { InspectionTemplate } from '../types'

interface Props {
  searchText: string
}

export const InspectionTemplates: React.FC<Props> = ({ searchText }) => {
  const [selectedTemplate, setSelectedTemplate] = useState<InspectionTemplate | null>(null)
  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null)

  const { data: templatesData, isLoading } = useInspectionTemplates()
  const cloneTemplate = useCloneTemplate()

  const templates: InspectionTemplate[] = templatesData?.items || []

  // 过滤模板列表
  const filteredTemplates = templates.filter(template => 
    template.name.toLowerCase().includes(searchText.toLowerCase()) ||
    template.description.toLowerCase().includes(searchText.toLowerCase())
  )

  const handleCloneTemplate = async (template: InspectionTemplate) => {
    try {
      await cloneTemplate.mutateAsync({
        id: template.id,
        name: `${template.name} - 副本`
      })
    } catch (error) {
      console.error('Clone template failed:', error)
    }
  }

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case 'network':
        return <Monitor className="w-4 h-4" />
      case 'system':
        return <Settings className="w-4 h-4" />
      case 'security':
        return <Shield className="w-4 h-4" />
      default:
        return <FileText className="w-4 h-4" />
    }
  }

  const getCategoryLabel = (category: string) => {
    const labels = {
      network: '网络监控',
      system: '系统检查',
      security: '安全检测',
      custom: '自定义'
    }
    return labels[category as keyof typeof labels] || category
  }

  const getCategoryBadgeVariant = (category: string) => {
    switch (category) {
      case 'network':
        return 'primary'
      case 'system':
        return 'secondary'
      case 'security':
        return 'warning'
      default:
        return 'outline'
    }
  }

  const columns: Column<InspectionTemplate>[] = [
    {
      key: 'name',
      title: '模板名称',
      render: (template) => (
        <div className="flex flex-col">
          <div className="flex items-center gap-2">
            {getCategoryIcon(template.category)}
            <span className="font-medium text-gray-900">{template.name}</span>
            {template.isBuiltIn && (
              <Badge variant="success" size="sm">内置</Badge>
            )}
          </div>
          <span className="text-sm text-gray-500 line-clamp-2 mt-1">{template.description}</span>
        </div>
      )
    },
    {
      key: 'category',
      title: '类别',
      render: (template) => (
        <Badge variant={getCategoryBadgeVariant(template.category) as any}>
          {getCategoryLabel(template.category)}
        </Badge>
      )
    },
    {
      key: 'deviceTypes',
      title: '支持设备',
      render: (template) => (
        <div className="flex flex-wrap gap-1">
          {template.deviceTypes.slice(0, 3).map((type: string) => (
            <Badge key={type} variant="outline" size="sm">
              {type}
            </Badge>
          ))}
          {template.deviceTypes.length > 3 && (
            <Badge variant="outline" size="sm">
              +{template.deviceTypes.length - 3}
            </Badge>
          )}
        </div>
      )
    },
    {
      key: 'checkItems',
      title: '检查项',
      render: (template) => (
        <div className="flex items-center gap-1">
          <FileText className="w-4 h-4 text-gray-400" />
          <span className="font-medium">{template.checkItems.length}</span>
        </div>
      )
    },
    {
      key: 'updatedAt',
      title: '更新时间',
      render: (template) => (
        <div className="text-sm text-gray-600">
          {new Date(template.updatedAt).toLocaleDateString()}
        </div>
      )
    },
    {
      key: 'actions',
      title: '操作',
      render: (template) => (
        <div className="flex items-center gap-1">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => setSelectedTemplate(template)}
            title="查看详情"
          >
            <Eye className="w-4 h-4" />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => handleCloneTemplate(template)}
            disabled={cloneTemplate.isPending}
            title="复制模板"
          >
            <Copy className="w-4 h-4" />
          </Button>
          {!template.isBuiltIn && (
            <>
              <Button
                size="sm"
                variant="ghost"
                title="编辑"
              >
                <Edit className="w-4 h-4" />
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => setDeleteConfirm(template.id)}
                title="删除"
              >
                <Trash2 className="w-4 h-4 text-red-500" />
              </Button>
            </>
          )}
        </div>
      )
    }
  ]

  if (isLoading) {
    return (
      <div className="space-y-4">
        {/* 加载骨架屏 */}
        {[...Array(5)].map((_, index) => (
          <Card key={index} className="animate-pulse">
            <CardContent className="p-4">
              <div className="flex items-center gap-4">
                <div className="h-4 bg-gray-200 rounded w-1/4"></div>
                <div className="h-4 bg-gray-200 rounded w-1/6"></div>
                <div className="h-4 bg-gray-200 rounded w-1/6"></div>
                <div className="h-4 bg-gray-200 rounded w-1/4"></div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* 操作栏 */}
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
          <h3 className="text-lg font-semibold">巡检模板管理</h3>
          <Badge variant="secondary">{filteredTemplates.length} 项</Badge>
        </div>
        <div className="flex gap-2">
          <Button variant="outline">
            <Copy className="w-4 h-4 mr-2" />
            导入模板
          </Button>
          <Button>
            <Plus className="w-4 h-4 mr-2" />
            创建模板
          </Button>
        </div>
      </div>

      {/* 快速统计 */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          { label: '网络监控', count: templates.filter(t => t.category === 'network').length, icon: Monitor, color: 'blue' },
          { label: '系统检查', count: templates.filter(t => t.category === 'system').length, icon: Settings, color: 'green' },
          { label: '安全检测', count: templates.filter(t => t.category === 'security').length, icon: Shield, color: 'red' },
          { label: '自定义', count: templates.filter(t => t.category === 'custom').length, icon: FileText, color: 'purple' }
        ].map((item) => (
          <Card key={item.label}>
            <CardContent className="p-4">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg bg-${item.color}-100`}>
                  <item.icon className={`w-5 h-5 text-${item.color}-600`} />
                </div>
                <div>
                  <div className="text-2xl font-bold text-gray-900">{item.count}</div>
                  <div className="text-sm text-gray-600">{item.label}</div>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* 模板列表 */}
      {filteredTemplates.length > 0 ? (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.3 }}
        >
          <Table
            data={filteredTemplates}
            columns={columns}
            className="bg-white rounded-lg shadow-sm"
          />
        </motion.div>
      ) : (
        <Card>
          <CardContent className="p-8 text-center">
            <div className="flex flex-col items-center gap-4">
              <AlertCircle className="w-12 h-12 text-gray-400" />
              <div>
                <h3 className="text-lg font-medium text-gray-900">暂无巡检模板</h3>
                <p className="text-gray-500 mt-1">
                  {searchText ? '没有找到匹配的模板' : '开始创建您的第一个巡检模板'}
                </p>
              </div>
              {!searchText && (
                <Button className="mt-2">
                  <Plus className="w-4 h-4 mr-2" />
                  创建模板
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* 删除确认弹窗 */}
      {/* <ConfirmModal
        open={!!deleteConfirm}
        onClose={() => setDeleteConfirm(null)}
        onConfirm={() => {
          // 删除逻辑
          setDeleteConfirm(null)
        }}
        title="删除模板"
        description="确定要删除这个巡检模板吗？此操作无法撤销。"
        confirmText="删除"
        cancelText="取消"
        variant="destructive"
      /> */}
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { X, Calendar, Users, FileText, Plus, Trash2 } from 'lucide-react'
import {
  Button,
  SimpleInput as Input,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Badge
} from '@/components/atoms'
import { useCreateStrategy, useUpdateStrategy } from '../hooks/useInspection'
import { InspectionStrategy } from '../types'

interface Props {
  strategy: InspectionStrategy | null
  onClose: () => void
  onSuccess: () => void
}

export const StrategyModal: React.FC<Props> = ({ strategy, onClose, onSuccess }) => {
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    type: 'scheduled' as 'scheduled' | 'manual',
    cron: '0 0 2 * * ?', // 每天凌晨2点
    devices: [] as string[],
    templates: [] as string[],
    enabled: true
  })

  const [errors, setErrors] = useState<Record<string, string>>({})
  const createStrategy = useCreateStrategy()
  const updateStrategy = useUpdateStrategy()

  const isEditing = !!strategy

  useEffect(() => {
    if (strategy) {
      setFormData({
        name: strategy.name,
        description: strategy.description,
        type: strategy.type,
        cron: strategy.cron || '0 0 2 * * ?',
        devices: strategy.devices,
        templates: strategy.templates,
        enabled: strategy.enabled
      })
    }
  }, [strategy])

  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }))

    // 清除字段错误
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: ''
      }))
    }
  }

  const validateForm = () => {
    const newErrors: Record<string, string> = {}

    if (!formData.name.trim()) {
      newErrors.name = '请输入策略名称'
    }

    if (!formData.description.trim()) {
      newErrors.description = '请输入策略描述'
    }

    if (formData.type === 'scheduled' && !formData.cron.trim()) {
      newErrors.cron = '请输入Cron表达式'
    }

    if (formData.devices.length === 0) {
      newErrors.devices = '请选择至少一个设备'
    }

    if (formData.templates.length === 0) {
      newErrors.templates = '请选择至少一个模板'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    try {
      if (isEditing && strategy) {
        await updateStrategy.mutateAsync({
          id: strategy.id,
          data: formData
        })
      } else {
        await createStrategy.mutateAsync(formData)
      }
      onSuccess()
    } catch (error) {
      console.error('Save strategy failed:', error)
    }
  }

  const cronPresets = [
    { label: '每天凌晨2点', value: '0 0 2 * * ?' },
    { label: '每小时执行', value: '0 0 * * * ?' },
    { label: '每30分钟执行', value: '0 */30 * * * ?' },
    { label: '每周一凌晨2点', value: '0 0 2 ? * MON' },
    { label: '每月1号凌晨2点', value: '0 0 2 1 * ?' },
  ]

  const isLoading = createStrategy.isPending || updateStrategy.isPending

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-hidden"
      >
        {/* 头部 */}
        <div className="flex items-center justify-between p-6 border-b">
          <div>
            <h2 className="text-xl font-semibold text-gray-900">
              {isEditing ? '编辑巡检策略' : '创建巡检策略'}
            </h2>
            <p className="text-sm text-gray-500 mt-1">
              配置巡检策略的基本信息和执行规则
            </p>
          </div>
          <Button variant="ghost" size="sm" onClick={onClose}>
            <X className="w-5 h-5" />
          </Button>
        </div>

        {/* 表单内容 */}
        <form onSubmit={handleSubmit} className="p-6 overflow-y-auto">
          <div className="space-y-6">
            {/* 基本信息 */}
            <div className="space-y-4">
              <h3 className="text-lg font-medium flex items-center gap-2">
                <FileText className="w-5 h-5 text-blue-600" />
                基本信息
              </h3>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    策略名称 *
                  </label>
                  <Input
                    value={formData.name}
                    onChange={(e) => handleInputChange('name', e.target.value)}
                    placeholder="请输入策略名称"
                    className={errors.name ? 'border-red-500' : ''}
                  />
                  {errors.name && (
                    <p className="text-sm text-red-500 mt-1">{errors.name}</p>
                  )}
                </div>

                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    策略描述 *
                  </label>
                  <textarea
                    value={formData.description}
                    onChange={(e) => handleInputChange('description', e.target.value)}
                    placeholder="请输入策略描述"
                    className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 ${
                      errors.description ? 'border-red-500' : 'border-gray-300'
                    }`}
                    rows={3}
                  />
                  {errors.description && (
                    <p className="text-sm text-red-500 mt-1">{errors.description}</p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    策略类型 *
                  </label>
                  <Select
                    value={formData.type}
                    onValueChange={(value) => handleInputChange('type', value)}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="选择策略类型" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="scheduled">定时巡检</SelectItem>
                      <SelectItem value="manual">手动巡检</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="flex items-center gap-2">
                  <label className="flex items-center">
                    <input
                      type="checkbox"
                      checked={formData.enabled}
                      onChange={(e) => handleInputChange('enabled', e.target.checked)}
                      className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                    />
                    <span className="ml-2 text-sm text-gray-700">启用策略</span>
                  </label>
                </div>
              </div>
            </div>

            {/* 执行时间配置 */}
            {formData.type === 'scheduled' && (
              <div className="space-y-4">
                <h3 className="text-lg font-medium flex items-center gap-2">
                  <Calendar className="w-5 h-5 text-purple-600" />
                  执行时间
                </h3>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Cron表达式 *
                  </label>
                  <div className="flex gap-2">
                    <Input
                      value={formData.cron}
                      onChange={(e) => handleInputChange('cron', e.target.value)}
                      placeholder="0 0 2 * * ?"
                      error={errors.cron}
                      className="flex-1"
                    />
                    <Select onValueChange={(value) => handleInputChange('cron', value)}>
                      <SelectTrigger className="w-48">
                        <SelectValue placeholder="常用预设" />
                      </SelectTrigger>
                      <SelectContent>
                        {cronPresets.map((preset) => (
                          <SelectItem key={preset.value} value={preset.value}>
                            {preset.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <p className="text-xs text-gray-500 mt-1">
                    格式：秒 分 时 日 月 周，例如：0 0 2 * * ? 表示每天凌晨2点执行
                  </p>
                </div>
              </div>
            )}

            {/* 设备和模板选择 */}
            <div className="space-y-4">
              <h3 className="text-lg font-medium flex items-center gap-2">
                <Users className="w-5 h-5 text-green-600" />
                目标配置
              </h3>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    目标设备 * ({formData.devices.length} 个)
                  </label>
                  <div className="border border-gray-300 rounded-lg p-3 min-h-[100px] bg-gray-50">
                    <div className="flex flex-wrap gap-2">
                      {formData.devices.map((deviceId) => (
                        <Badge key={deviceId} variant="secondary" className="flex items-center gap-1">
                          设备-{deviceId}
                          <button
                            type="button"
                            onClick={() => {
                              const newDevices = formData.devices.filter(id => id !== deviceId)
                              handleInputChange('devices', newDevices)
                            }}
                            className="ml-1 hover:text-red-500"
                          >
                            <X className="w-3 h-3" />
                          </button>
                        </Badge>
                      ))}
                    </div>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="mt-2"
                      onClick={() => {
                        // 这里应该打开设备选择弹窗
                        const mockDeviceId = `device-${Date.now()}`
                        handleInputChange('devices', [...formData.devices, mockDeviceId])
                      }}
                    >
                      <Plus className="w-4 h-4 mr-1" />
                      添加设备
                    </Button>
                  </div>
                  {errors.devices && (
                    <p className="text-sm text-red-500 mt-1">{errors.devices}</p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    巡检模板 * ({formData.templates.length} 个)
                  </label>
                  <div className="border border-gray-300 rounded-lg p-3 min-h-[100px] bg-gray-50">
                    <div className="flex flex-wrap gap-2">
                      {formData.templates.map((templateId) => (
                        <Badge key={templateId} variant="primary" className="flex items-center gap-1">
                          模板-{templateId}
                          <button
                            type="button"
                            onClick={() => {
                              const newTemplates = formData.templates.filter(id => id !== templateId)
                              handleInputChange('templates', newTemplates)
                            }}
                            className="ml-1 hover:text-red-500"
                          >
                            <X className="w-3 h-3" />
                          </button>
                        </Badge>
                      ))}
                    </div>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="mt-2"
                      onClick={() => {
                        // 这里应该打开模板选择弹窗
                        const mockTemplateId = `template-${Date.now()}`
                        handleInputChange('templates', [...formData.templates, mockTemplateId])
                      }}
                    >
                      <Plus className="w-4 h-4 mr-1" />
                      添加模板
                    </Button>
                  </div>
                  {errors.templates && (
                    <p className="text-sm text-red-500 mt-1">{errors.templates}</p>
                  )}
                </div>
              </div>
            </div>
          </div>
        </form>

        {/* 底部操作按钮 */}
        <div className="flex items-center justify-end gap-3 p-6 border-t bg-gray-50">
          <Button variant="outline" onClick={onClose} disabled={isLoading}>
            取消
          </Button>
          <Button type="submit" onClick={handleSubmit} disabled={isLoading}>
            {isLoading ? '保存中...' : isEditing ? '保存修改' : '创建策略'}
          </Button>
        </div>
      </motion.div>
    </div>
  )
}

