  }
}

// 停止实时监控
export async function stopRealTimeMonitoring(deviceIds?: number[]): Promise<boolean> {
  try {
    if (!deviceIds || deviceIds.length === 0) {
      return true
    }

    await Promise.all(
      deviceIds.map(deviceId =>
        api.post(`/monitoring/devices/${deviceId}/stop`, {
          device_id: deviceId,
          interval: 60,
