// 获取报表列表
export async function fetchReports(params?: {
  page?: number
  pageSize?: number
  type?: string
  status?: string
  createdBy?: string
  startDate?: string
  endDate?: string
}): Promise<{ reports: Report[]; total: number; pages: number }> {
  try {
    let endpoint = '/reports'
    const searchParams = new URLSearchParams()

    if (params) {
      if (params.page) searchParams.append('page', params.page.toString())
      if (params.pageSize) searchParams.append('page_size', params.pageSize.toString())
      if (params.type) searchParams.append('type', params.type)
      if (params.status) searchParams.append('status', params.status)
      if (params.createdBy) searchParams.append('created_by', params.createdBy)
      if (params.startDate) searchParams.append('start_date', params.startDate)
      if (params.endDate) searchParams.append('end_date', params.endDate)
    }

    if (searchParams.toString()) {
      endpoint += `?${searchParams.toString()}`
    }

    const response = await api.get<{success: boolean, data: any, message?: string}>(endpoint)

    if (response.success && response.data) {
      return {
        reports: response.data.reports?.map(transformReportData) || [],
        total: response.data.total || 0,
        pages: response.data.pages || 0,
      }
    } else {
      throw new Error(response.message || '获取报表列表失败')
    }
  } catch (error) {
    console.error('获取报表列表失败:', error)
    return {
      reports: getDefaultReports(),
      total: 0,
      pages: 0,
    }
  }
}

