// ==================== 数据转换函数 ====================

function transformReportData(apiData: any): Report {
  return {
    id: apiData.id?.toString() || String(Math.random()),
    title: apiData.title || apiData.name || '未命名报表',
    description: apiData.description || '',
    type: apiData.type || 'custom',
    category: apiData.category || 'general',
    status: apiData.status || 'pending',
    format: apiData.format || 'pdf',
    generatedBy: apiData.created_by || apiData.creator || '系统',
    createdAt: apiData.created_at || new Date().toISOString(),
    updatedAt: apiData.updated_at || apiData.created_at || new Date().toISOString(),
    parameters: apiData.parameters || {},
    downloadUrl: apiData.download_url,
    filePath: apiData.filePath,
    fileSize: apiData.size,
    schedule: apiData.schedule,
  }
}

function transformInspectionReportData(apiData: any): InspectionReportData {
  return {
    summary: {
      totalDevices: apiData.summary?.total_devices || 0,
      totalChecks: apiData.summary?.total_checks || 0,
      passedChecks: apiData.summary?.passed_checks || 0,
      failedChecks: apiData.summary?.failed_checks || 0,
      warningChecks: apiData.summary?.warning_checks || 0,
      avgScore: apiData.summary?.average_score || 0,
      successRate: apiData.summary?.success_rate || 0,
      totalExecutions: apiData.summary?.total_executions || 0,
    },
    deviceResults: apiData.device_results?.map((device: any) => ({
      deviceId: device.device_id,
      deviceName: device.device_name,
      status: device.status,
      score: device.score,
      checkResults: device.check_results || [],
    })) || [],
    executionTrends: apiData.execution_trends || [],
    problemAnalysis: apiData.problem_analysis || [],
    recommendations: apiData.recommendations || [],
  }
}

function transformTrendAnalysisData(apiData: any): TrendAnalysisData {
  return {
    timeRange: {
      startDate: apiData.time_range?.start_date || '',
      endDate: apiData.time_range?.end_date || ''
    },
    metrics: {
      availability: apiData.metrics?.availability || { name: 'availability', current: 0, previous: 0, change: 0, changePercentage: 0, trend: 'stable' as const, dataPoints: [] },
      performance: apiData.metrics?.performance || { name: 'performance', current: 0, previous: 0, change: 0, changePercentage: 0, trend: 'stable' as const, dataPoints: [] },
      errors: apiData.metrics?.errors || { name: 'errors', current: 0, previous: 0, change: 0, changePercentage: 0, trend: 'stable' as const, dataPoints: [] },
      capacity: apiData.metrics?.capacity || { name: 'capacity', current: 0, previous: 0, change: 0, changePercentage: 0, trend: 'stable' as const, dataPoints: [] }
    },
    predictions: apiData.predictions || [],
    alerts: apiData.alerts || [],
  }
}

function transformStatisticsData(apiData: any): StatisticsData {
  return {
    overview: {
      totalDevices: apiData.overview?.total_devices || 0,
      activeDevices: apiData.overview?.online_devices || 0,
      offlineDevices: apiData.overview?.offline_devices || 0,
      warningDevices: apiData.overview?.warning_devices || 0,
      errorDevices: apiData.overview?.error_devices || 0,
      avgUptime: apiData.overview?.average_uptime || 0,
      totalExecutions: apiData.overview?.total_executions || 0,
      avgScore: apiData.overview?.avg_score || 0,
    },
    deviceDistribution: apiData.device_distribution || { byType: {}, byGroup: {}, byStatus: {}, byLocation: {} },
    performanceStats: apiData.performance_stats || { byDevice: [], aggregated: { avgAvailability: 0, avgResponseTime: 0, avgErrorRate: 0, avgUtilization: 0, topPerformers: [], underPerformers: [] } },
    complianceStats: apiData.compliance_stats || { overallCompliance: 0, byCategory: {}, failedChecks: [] },
    historicalComparison: apiData.historical_comparison || { currentPeriod: { period: '', totalExecutions: 0, avgScore: 0, avgUptime: 0, issueCount: 0, resolvedIssueCount: 0 }, previousPeriod: { period: '', totalExecutions: 0, avgScore: 0, avgUptime: 0, issueCount: 0, resolvedIssueCount: 0 }, changes: {} },
  }
}

