    {
      key: 'users',
      label: '用户管理',
      icon: Users,
      description: '用户账户和角色权限管理'
    },
    {
      key: 'security',
      label: '安全设置',
      icon: Shield,
      description: '系统安全策略和访问控制',
      badge: systemHealth?.overall === 'critical' ? '警告' : undefined
    },
    {
      key: 'logs',
      label: '审计日志',
      icon: FileText,
      description: '系统操作日志和审计记录'
    },
    {
      key: 'backup',
      label: '备份恢复',
      icon: Database,
      description: '数据备份和系统恢复管理'
    },
    {
      key: 'notifications',
      label: '通知设置',
      icon: Bell,
      description: '告警通知和消息推送配置'
    },
    {
      key: 'monitoring',
      label: '系统监控',
      icon: Monitor,
      description: '系统性能监控和健康状态',
      badge: systemHealth?.overall === 'warning' ? '异常' : undefined
    },
    {
      key: 'license',
      label: '许可证',
      icon: Key,
      description: '系统许可证和授权管理'
    }
  ]

  const renderTabContent = () => {
    switch (activeTab) {
      case 'general':
        return <SystemConfiguration searchText={searchText} />
      case 'users':
        return <UserManagement searchText={searchText} />
      case 'security':
        return <SecuritySettings />
      case 'logs':
        return <AuditLogs searchText={searchText} />
      case 'backup':
        return <BackupRestore />
      case 'notifications':
        return <NotificationSettings />
      case 'monitoring':
        return <SystemMonitoring />
      case 'license':
        return <LicenseManagement />
      default:
        return null
    }
  }

  return (
    <AppLayout title="系统设置">
      <div className="space-y-6">
        {/* 系统状态卡片 */}
        {systemInfo && systemHealth && (
          <div className="flex gap-4">
            <Card className="min-w-[120px]">
              <CardContent className="p-4 text-center">
                <div className="text-sm font-medium text-gray-600">系统版本</div>
                <div className="text-lg font-bold text-gray-900 mt-1">{systemInfo.version}</div>
              </CardContent>
            </Card>
            <Card className="min-w-[120px]">
              <CardContent className="p-4 text-center">
                <div className="text-sm font-medium text-gray-600">运行状态</div>
                <div className={`text-lg font-bold mt-1 ${
                  systemHealth.overall === 'healthy' ? 'text-green-600' :
                  systemHealth.overall === 'warning' ? 'text-yellow-600' : 'text-red-600'
                }`}>
                  {systemHealth.overall === 'healthy' ? '正常' :
                   systemHealth.overall === 'warning' ? '警告' : '异常'}
                </div>
              </CardContent>
            </Card>
            <Card className="min-w-[120px]">
              <CardContent className="p-4 text-center">
                <div className="text-sm font-medium text-gray-600">运行时间</div>
                <div className="text-lg font-bold text-gray-900 mt-1">
                  {Math.floor(systemInfo.uptime / 86400)}天
                </div>
              </CardContent>
            </Card>
          </div>
        )}

        {/* 标签导航 */}
        <Card>
          <CardHeader className="pb-0">
            <div className="flex flex-col sm:flex-row gap-4 justify-between">
              {/* 标签按钮 */}
              <div className="flex flex-wrap gap-2">
                {tabs.map((tab) => {
                  const Icon = tab.icon
                  const isActive = activeTab === tab.key

                  return (
                    <motion.button
                      key={tab.key}
                      onClick={() => setActiveTab(tab.key)}
                      className={`
                        relative flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium
                        transition-all duration-200
                        ${isActive 
                          ? 'bg-blue-50 text-blue-600 shadow-sm' 
