                      {tab.label}
                      {tab.badge && (
                        <Badge variant="danger" size="sm" className="ml-1">
                          {tab.badge}
                        </Badge>
                      )}
                      {isActive && (
                        <motion.div
                          className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600 rounded-full"
                          layoutId="activeSettingsTabIndicator"
