                      )}
                    </motion.button>
                  )
                })}
              </div>

              {/* 搜索和操作按钮 */}
              <div className="flex gap-2">
                {['general', 'users', 'logs'].includes(activeTab) && (
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <Input
                      placeholder="搜索..."
                      value={searchText}
                      onChange={(e) => setSearchText(e.target.value)}
                      className="pl-10 w-48"
                    />
                  </div>
                )}
                <Button variant="outline" size="sm">
                  <Filter className="w-4 h-4 mr-2" />
                  筛选
                </Button>
                <Button variant="outline" size="sm">
                  <RefreshCw className="w-4 h-4 mr-2" />
                  刷新
                </Button>
              </div>
            </div>

            {/* 当前标签描述 */}
            <div className="pt-2">
              <p className="text-sm text-gray-600">
                {tabs.find(tab => tab.key === activeTab)?.description}
              </p>
            </div>
          </CardHeader>

          <CardContent className="pt-4">
            {/* 标签内容区域 */}
            <motion.div
              key={activeTab}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.2 }}
            >
              {renderTabContent()}
            </motion.div>
          </CardContent>
        </Card>
      </div>
    </AppLayout>
  )
}

import React, { useState } from 'react'
import { motion } from 'framer-motion'
import { 
  Settings, 
  Save, 
  RotateCcw, 
  Upload, 
  Download, 
  Edit, 
  Check, 
  X,
  AlertCircle,
  Info
} from 'lucide-react'
import {
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  Button,
  Badge,
  Input,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  ConfirmModal
} from '@/components/atoms'
import { 
  useConfigGroups,
  useSystemConfigs,
  useUpdateConfig,
  useUpdateConfigs,
  useResetConfig,
  useSettingsEditor
} from '../hooks/useSettings'
import { SystemConfig, SettingsGroup } from '../types'

interface Props {
  searchText: string
}

export const SystemConfiguration: React.FC<Props> = ({ searchText }) => {
  const [selectedGroup, setSelectedGroup] = useState('general')
  const [importModal, setImportModal] = useState(false)
  const [resetConfirm, setResetConfirm] = useState<string | null>(null)

  const { data: configGroups, isLoading: groupsLoading } = useConfigGroups()
  const { data: configs, isLoading: configsLoading } = useSystemConfigs(selectedGroup)
  const updateConfig = useUpdateConfig()
  const updateConfigs = useUpdateConfigs()
  const resetConfig = useResetConfig()
  const { editingConfig, pendingChanges, hasPendingChanges, startEditing, stopEditing, updatePendingChange } = useSettingsEditor()

  const groups = configGroups || []
  const filteredConfigs = (configs || []).filter(config =>
    config.label.toLowerCase().includes(searchText.toLowerCase()) ||
    config.description.toLowerCase().includes(searchText.toLowerCase())
  )

  const handleEditConfig = (config: SystemConfig) => {
    startEditing(config.key)
    updatePendingChange(config.key, config.value)
  }

  const handleSaveConfig = async (config: SystemConfig) => {
    const newValue = pendingChanges[config.key]
    if (newValue !== undefined && newValue !== config.value) {
      try {
        await updateConfig.mutateAsync({ key: config.key, value: newValue })
        stopEditing()
      } catch (error) {
        console.error('Save config failed:', error)
      }
    } else {
      stopEditing()
    }
  }

  const handleSaveAllChanges = async () => {
    if (!hasPendingChanges) return

    const configsToUpdate = Object.entries(pendingChanges)
      .filter(([key, value]) => {
        const config = filteredConfigs.find(c => c.key === key)
        return config && value !== config.value
      })
      .map(([key, value]) => ({ key, value }))

    if (configsToUpdate.length > 0) {
      try {
        await updateConfigs.mutateAsync(configsToUpdate)
        stopEditing()
      } catch (error) {
        console.error('Save configs failed:', error)
      }
    }
  }

  const handleResetConfig = async (configKey: string) => {
    try {
      await resetConfig.mutateAsync(configKey)
      setResetConfirm(null)
    } catch (error) {
      console.error('Reset config failed:', error)
    }
  }

  const renderConfigValue = (config: SystemConfig) => {
    const isEditing = editingConfig === config.key
    const currentValue = isEditing ? (pendingChanges[config.key] ?? config.value) : config.value

    if (config.readonly) {
      return (
        <div className="flex items-center gap-2">
          <span className="text-gray-900">{String(currentValue)}</span>
          <Badge variant="secondary" size="sm">只读</Badge>
        </div>
      )
    }

    if (isEditing) {
      switch (config.type) {
        case 'boolean':
          return (
            <div className="flex items-center gap-2">
              <Select
                value={String(currentValue)}
                onValueChange={(value) => updatePendingChange(config.key, value === 'true')}
              >
                <SelectTrigger className="w-32">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="true">启用</SelectItem>
                  <SelectItem value="false">禁用</SelectItem>
                </SelectContent>
              </Select>
              <Button size="sm" onClick={() => handleSaveConfig(config)}>
                <Check className="w-4 h-4" />
              </Button>
              <Button size="sm" variant="ghost" onClick={stopEditing}>
                <X className="w-4 h-4" />
              </Button>
            </div>
          )

        case 'number':
          return (
            <div className="flex items-center gap-2">
              <Input
                type="number"
                value={currentValue}
                onChange={(e) => updatePendingChange(config.key, Number(e.target.value))}
                min={config.validation?.min}
                max={config.validation?.max}
                className="w-32"
              />
              <Button size="sm" onClick={() => handleSaveConfig(config)}>
                <Check className="w-4 h-4" />
              </Button>
              <Button size="sm" variant="ghost" onClick={stopEditing}>
                <X className="w-4 h-4" />
              </Button>
            </div>
          )

        case 'array':
          if (config.validation?.options) {
            return (
              <div className="flex items-center gap-2">
                <Select
                  value={Array.isArray(currentValue) ? currentValue.join(',') : String(currentValue)}
                  onValueChange={(value) => updatePendingChange(config.key, value.split(','))}
                >
                  <SelectTrigger className="w-48">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {config.validation.options.map((option) => (
                      <SelectItem key={option.value} value={String(option.value)}>
                        {option.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Button size="sm" onClick={() => handleSaveConfig(config)}>
                  <Check className="w-4 h-4" />
                </Button>
                <Button size="sm" variant="ghost" onClick={stopEditing}>
                  <X className="w-4 h-4" />
                </Button>
              </div>
            )
          }
          break

        default:
          return (
            <div className="flex items-center gap-2">
              <Input
                value={String(currentValue)}
                onChange={(e) => updatePendingChange(config.key, e.target.value)}
                className="w-48"
                pattern={config.validation?.pattern}
              />
              <Button size="sm" onClick={() => handleSaveConfig(config)}>
                <Check className="w-4 h-4" />
              </Button>
              <Button size="sm" variant="ghost" onClick={stopEditing}>
                <X className="w-4 h-4" />
              </Button>
            </div>
          )
      }
    }

    // 只读显示
    return (
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="text-gray-900">
            {config.type === 'boolean' 
              ? (currentValue ? '启用' : '禁用')
              : Array.isArray(currentValue) 
                ? currentValue.join(', ')
                : String(currentValue)
            }
          </span>
          {config.type === 'boolean' && (
            <div className={`w-2 h-2 rounded-full ${currentValue ? 'bg-green-500' : 'bg-gray-400'}`} />
          )}
        </div>
        <div className="flex items-center gap-1">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => handleEditConfig(config)}
            disabled={config.readonly}
          >
            <Edit className="w-4 h-4" />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => setResetConfirm(config.key)}
            disabled={config.readonly}
          >
            <RotateCcw className="w-4 h-4" />
          </Button>
        </div>
      </div>
    )
  }

  if (groupsLoading || configsLoading) {
    return (
      <div className="space-y-4">
        {[...Array(5)].map((_, index) => (
          <Card key={index} className="animate-pulse">
            <CardContent className="p-4">
              <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
              <div className="h-3 bg-gray-200 rounded w-1/2"></div>
            </CardContent>
          </Card>
        ))}
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* 操作栏 */}
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-4">
          <h3 className="text-lg font-semibold">系统配置管理</h3>
          {hasPendingChanges && (
            <Badge variant="warning">
              {Object.keys(pendingChanges).length} 项待保存
            </Badge>
          )}
        </div>
        <div className="flex gap-2">
          {hasPendingChanges && (
            <>
              <Button variant="outline" onClick={stopEditing}>
                取消修改
              </Button>
              <Button onClick={handleSaveAllChanges}>
                <Save className="w-4 h-4 mr-2" />
                保存全部
              </Button>
            </>
          )}
          <Button variant="outline" onClick={() => setImportModal(true)}>
            <Upload className="w-4 h-4 mr-2" />
            导入配置
          </Button>
          <Button variant="outline">
            <Download className="w-4 h-4 mr-2" />
            导出配置
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* 配置分组侧边栏 */}
        <div className="lg:col-span-1">
          <Card>
            <CardHeader>
              <CardTitle className="text-sm">配置分组</CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              <div className="space-y-1">
                {groups.map((group) => (
                  <button
                    key={group.id}
                    onClick={() => setSelectedGroup(group.name)}
                    className={`w-full text-left px-4 py-3 text-sm transition-colors ${
                      selectedGroup === group.name
                        ? 'bg-blue-50 text-blue-600 border-r-2 border-blue-600'
                        : 'text-gray-700 hover:bg-gray-50'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <span className="font-medium">{group.displayName}</span>
                      <Badge variant="outline" size="sm">
                        {group.configs.length}
                      </Badge>
                    </div>
                  </button>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* 配置项列表 */}
        <div className="lg:col-span-3">
          <div className="space-y-4">
            {filteredConfigs.length > 0 ? (
              filteredConfigs.map((config) => (
                <motion.div
                  key={config.id}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.2 }}
                >
                  <Card className={`${editingConfig === config.key ? 'ring-2 ring-blue-500' : ''}`}>
                    <CardContent className="p-6">
                      <div className="flex items-start justify-between">
                        <div className="flex-1 min-w-0 mr-4">
                          <div className="flex items-center gap-2 mb-2">
                            <h4 className="text-base font-medium text-gray-900">
                              {config.label}
                            </h4>
                            {config.required && (
                              <Badge variant="primary" size="sm">必需</Badge>
                            )}
                          </div>
                          <p className="text-sm text-gray-600 mb-3">
                            {config.description}
                          </p>
                          <div className="flex items-center gap-2 text-xs text-gray-500">
                            <span>配置键: {config.key}</span>
                            <span>•</span>
                            <span>类型: {config.type}</span>
                            <span>•</span>
                            <span>最后更新: {new Date(config.updatedAt).toLocaleString()}</span>
                          </div>
                        </div>
                        <div className="flex-shrink-0 min-w-[200px]">
                          {renderConfigValue(config)}
                        </div>
                      </div>

                      {config.validation && (
                        <div className="mt-4 p-3 bg-blue-50 rounded-lg">
                          <div className="flex items-start gap-2">
                            <Info className="w-4 h-4 text-blue-600 mt-0.5" />
                            <div className="text-xs text-blue-700">
                              <div className="font-medium mb-1">验证规则:</div>
                              <ul className="space-y-1">
                                {config.validation.min !== undefined && (
                                  <li>最小值: {config.validation.min}</li>
                                )}
                                {config.validation.max !== undefined && (
                                  <li>最大值: {config.validation.max}</li>
                                )}
                                {config.validation.pattern && (
                                  <li>格式: {config.validation.pattern}</li>
                                )}
                                {config.validation.options && (
                                  <li>可选项: {config.validation.options.map(o => o.label).join(', ')}</li>
                                )}
                              </ul>
                            </div>
                          </div>
                        </div>
                      )}
                    </CardContent>
                  </Card>
                </motion.div>
              ))
            ) : (
              <Card>
                <CardContent className="p-8 text-center">
                  <Settings className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                  <h3 className="text-lg font-medium text-gray-900 mb-2">
                    {searchText ? '没有找到匹配的配置' : '暂无配置项'}
                  </h3>
                  <p className="text-gray-600">
                    {searchText ? '尝试调整搜索条件' : '该分组暂时没有可配置的项目'}
                  </p>
                </CardContent>
              </Card>
            )}
          </div>
        </div>
      </div>

      {/* 重置确认弹窗 */}
      <ConfirmModal
        isOpen={!!resetConfirm}
        onClose={() => setResetConfirm(null)}
        onConfirm={() => resetConfirm && handleResetConfig(resetConfirm)}
        title="重置配置"
        description="确定要将此配置重置为默认值吗？此操作无法撤销。"
        confirmText="重置"
        cancelText="取消"
        variant="default"
      />

      {/* 导入配置弹窗 */}
      {importModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white rounded-xl shadow-xl max-w-md w-full"
          >
            <div className="p-6">
              <h3 className="text-lg font-semibold mb-4">导入配置文件</h3>
              <div className="space-y-4">
                <div className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center">
                  <Upload className="w-8 h-8 text-gray-400 mx-auto mb-2" />
                  <p className="text-sm text-gray-600 mb-2">拖拽文件到此处或点击选择</p>
                  <input
                    type="file"
                    accept=".json,.yaml,.yml"
                    className="hidden"
                    id="config-file"
                  />
                  <label
                    htmlFor="config-file"
                    className="inline-flex items-center px-3 py-2 bg-blue-600 text-white text-sm rounded cursor-pointer hover:bg-blue-700"
                  >
                    选择文件
                  </label>
                </div>
                <div className="flex items-start gap-2 p-3 bg-yellow-50 rounded-lg">
                  <AlertCircle className="w-4 h-4 text-yellow-600 mt-0.5" />
                  <div className="text-xs text-yellow-700">
                    <div className="font-medium mb-1">注意事项:</div>
                    <ul className="space-y-1">
                      <li>• 仅支持 JSON 和 YAML 格式</li>
                      <li>• 导入前会验证配置格式</li>
                      <li>• 建议先备份现有配置</li>
                    </ul>
                  </div>
                </div>
              </div>
              <div className="flex justify-end gap-2 mt-6">
                <Button variant="outline" onClick={() => setImportModal(false)}>
                  取消
                </Button>
                <Button>导入</Button>
              </div>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  )
}

'use client'

import React, { useState, useCallback } from 'react'
import { Upload, Download, FileText, AlertTriangle, CheckCircle, X, User, Mail } from 'lucide-react'
import { Button, Card, CardContent, Badge, Table } from '@/components/atoms'
import { UserBulkImport as UserBulkImportType, UserRole } from '../types'

interface Props {
  onSubmit: (data: UserBulkImportType) => Promise<void>
  onCancel: () => void
}

interface ImportUser {
  username: string
  email: string
  fullName?: string
  role: UserRole
  password?: string
  errors?: string[]
}

// 模板数据
const TEMPLATE_DATA = [
  {
    username: 'john.doe',
    email: 'john.doe@example.com',
    fullName: 'John Doe',
    role: 'operator',
    password: ''
  },
  {
    username: 'jane.smith',
    email: 'jane.smith@example.com', 
    fullName: 'Jane Smith',
    role: 'viewer',
    password: ''
  }
]

export const UserBulkImport: React.FC<Props> = ({ onSubmit, onCancel }) => {
  const [step, setStep] = useState<'upload' | 'preview' | 'importing' | 'completed'>('upload')
  const [importData, setImportData] = useState<ImportUser[]>([])
  const [sendEmail, setSendEmail] = useState(true)
  const [forcePasswordChange, setForcePasswordChange] = useState(true)
  const [validUsers, setValidUsers] = useState<ImportUser[]>([])
  const [invalidUsers, setInvalidUsers] = useState<ImportUser[]>([])
  const [importProgress, setImportProgress] = useState(0)
  const [importResult, setImportResult] = useState<any>(null)

  // 下载模板文件
  const downloadTemplate = useCallback(() => {
    const csvContent = [
      'username,email,fullName,role,password',
      ...TEMPLATE_DATA.map(user => 
        `${user.username},${user.email},${user.fullName},${user.role},${user.password}`
      )
    ].join('\n')

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
    const link = document.createElement('a')
    const url = URL.createObjectURL(blob)
    link.setAttribute('href', url)
    link.setAttribute('download', 'user_import_template.csv')
    link.style.visibility = 'hidden'
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
  }, [])

  // 处理文件上传
  const handleFileUpload = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = (e) => {
      const content = e.target?.result as string
      parseCSVContent(content)
    }
    reader.readAsText(file)
  }, [])

  // 解析CSV内容
  const parseCSVContent = useCallback((content: string) => {
    try {
      const lines = content.split('\n').filter(line => line.trim())
      if (lines.length < 2) {
        throw new Error('文件内容格式不正确')
      }

      const headers = lines[0].split(',').map(h => h.trim().toLowerCase())
      const requiredHeaders = ['username', 'email']
      const missingHeaders = requiredHeaders.filter(h => !headers.includes(h))

      if (missingHeaders.length > 0) {
        throw new Error(`缺少必需的列: ${missingHeaders.join(', ')}`)
      }

      const users: ImportUser[] = []

      for (let i = 1; i < lines.length; i++) {
        const values = lines[i].split(',').map(v => v.trim().replace(/^"|"$/g, ''))
        const user: ImportUser = {
          username: '',
          email: '',
          role: 'viewer' as UserRole
        }

        headers.forEach((header, index) => {
          const value = values[index] || ''
          switch (header) {
            case 'username':
              user.username = value
              break
            case 'email':
              user.email = value
              break
            case 'fullname':
            case 'full_name':
              user.fullName = value
              break
            case 'role':
              user.role = ['admin', 'operator', 'viewer'].includes(value) 
                ? value as UserRole 
                : 'viewer'
              break
            case 'password':
              user.password = value
              break
          }
        })

        if (user.username && user.email) {
          users.push(user)
        }
      }

      setImportData(users)
      validateUsers(users)
      setStep('preview')
    } catch (error) {
      console.error('解析文件失败:', error)
      alert('文件解析失败，请检查文件格式')
    }
  }, [])

  // 验证用户数据
  const validateUsers = useCallback((users: ImportUser[]) => {
    const valid: ImportUser[] = []
    const invalid: ImportUser[] = []

    users.forEach(user => {
      const errors: string[] = []

      // 验证用户名
      if (!user.username) {
        errors.push('用户名不能为空')
      } else if (!/^[a-zA-Z0-9_-]+$/.test(user.username)) {
        errors.push('用户名格式无效')
      }

      // 验证邮箱
      if (!user.email) {
        errors.push('邮箱不能为空')
      } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(user.email)) {
        errors.push('邮箱格式无效')
      }

      // 验证角色
      if (!['admin', 'operator', 'viewer'].includes(user.role)) {
        errors.push('角色无效')
      }

      if (errors.length > 0) {
        invalid.push({ ...user, errors })
      } else {
        valid.push(user)
      }
    })

    // 检查重复用户名和邮箱
    const usernameSet = new Set<string>()
    const emailSet = new Set<string>()

    valid.forEach((user, index) => {
      if (usernameSet.has(user.username)) {
        const existingIndex = valid.findIndex(u => u.username === user.username)
        if (existingIndex !== index) {
          invalid.push({ ...user, errors: ['用户名重复'] })
          valid.splice(index, 1)
        }
      } else {
        usernameSet.add(user.username)
      }

      if (emailSet.has(user.email)) {
        const existingIndex = valid.findIndex(u => u.email === user.email)
        if (existingIndex !== index) {
          invalid.push({ ...user, errors: ['邮箱重复'] })
          valid.splice(index, 1)
        }
      } else {
        emailSet.add(user.email)
      }
    })

    setValidUsers(valid)
    setInvalidUsers(invalid)
  }, [])

  // 手动添加用户
  const addManualUser = useCallback(() => {
    const newUser: ImportUser = {
      username: '',
      email: '',
      role: 'viewer'
    }
    setImportData([...importData, newUser])
  }, [importData])

  // 更新用户数据
  const updateUser = useCallback((index: number, field: keyof ImportUser, value: string) => {
    const newData = [...importData]
    newData[index] = { ...newData[index], [field]: value }
    setImportData(newData)
    validateUsers(newData)
  }, [importData, validateUsers])

  // 删除用户
  const removeUser = useCallback((index: number) => {
    const newData = importData.filter((_, i) => i !== index)
    setImportData(newData)
    validateUsers(newData)
  }, [importData, validateUsers])

  // 执行导入
  const handleImport = useCallback(async () => {
    if (validUsers.length === 0) return

    setStep('importing')
    setImportProgress(0)

    try {
      // 模拟导入进度
      const progressInterval = setInterval(() => {
        setImportProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval)
            return prev
          }
          return prev + 10
        })
      }, 200)

      const bulkImportData = {
        users: validUsers.map(user => ({
          username: user.username,
          email: user.email,
          fullName: user.fullName,
          role: user.role,
          password: user.password
        })),
        sendEmail,
        forcePasswordChange
      }

      const result = await onSubmit(bulkImportData as any)
      setImportResult(result)
      setImportProgress(100)
      setStep('completed')
    } catch (error) {
      console.error('导入失败:', error)
      alert('导入失败，请稍后重试')
      setStep('preview')
    }
  }, [validUsers, sendEmail, forcePasswordChange, onSubmit])

  // 角色标签颜色
  const getRoleColor = (role: UserRole) => {
    switch (role) {
      case 'admin': return 'bg-red-100 text-red-800'
      case 'operator': return 'bg-blue-100 text-blue-800'
      case 'viewer': return 'bg-gray-100 text-gray-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  // 角色显示名称
  const getRoleLabel = (role: UserRole) => {
    switch (role) {
      case 'admin': return '管理员'
      case 'operator': return '操作员'
      case 'viewer': return '查看者'
      default: return '未知'
    }
  }

  return (
    <div className="space-y-6">
      {/* 步骤指示器 */}
      <div className="flex items-center justify-center space-x-4 mb-6">
        <div className={`flex items-center space-x-2 ${step === 'upload' ? 'text-blue-600' : 'text-green-600'}`}>
          <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
            step === 'upload' ? 'bg-blue-600 text-white' : 'bg-green-600 text-white'
          }`}>1</div>
          <span className="font-medium">上传文件</span>
        </div>

        <div className={`w-12 h-0.5 ${step === 'preview' || step === 'importing' || step === 'completed' ? 'bg-green-600' : 'bg-gray-300'}`} />

        <div className={`flex items-center space-x-2 ${
          step === 'preview' ? 'text-blue-600' : 
          step === 'importing' || step === 'completed' ? 'text-green-600' : 'text-gray-400'
        }`}>
          <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
            step === 'preview' ? 'bg-blue-600 text-white' :
            step === 'importing' || step === 'completed' ? 'bg-green-600 text-white' : 'bg-gray-300 text-gray-600'
          }`}>2</div>
          <span className="font-medium">预览数据</span>
        </div>

        <div className={`w-12 h-0.5 ${step === 'importing' || step === 'completed' ? 'bg-green-600' : 'bg-gray-300'}`} />

        <div className={`flex items-center space-x-2 ${
          step === 'importing' ? 'text-blue-600' : 
          step === 'completed' ? 'text-green-600' : 'text-gray-400'
        }`}>
          <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
            step === 'importing' ? 'bg-blue-600 text-white' :
            step === 'completed' ? 'bg-green-600 text-white' : 'bg-gray-300 text-gray-600'
          }`}>3</div>
          <span className="font-medium">导入完成</span>
        </div>
      </div>

      {/* 上传步骤 */}
      {step === 'upload' && (
        <div className="space-y-6">
          {/* 下载模板 */}
          <Card>
            <CardContent className="p-6">
              <h4 className="text-lg font-medium mb-4 flex items-center">
                <Download className="w-5 h-5 mr-2" />
                第一步：下载导入模板
              </h4>
              <p className="text-gray-600 mb-4">
                请先下载模板文件，按照模板格式填写用户信息后上传。
              </p>
              <Button onClick={downloadTemplate} variant="outline">
                <Download className="w-4 h-4 mr-2" />
                下载 CSV 模板
              </Button>
            </CardContent>
          </Card>

          {/* 文件上传 */}
          <Card>
            <CardContent className="p-6">
              <h4 className="text-lg font-medium mb-4 flex items-center">
                <Upload className="w-5 h-5 mr-2" />
                第二步：上传用户数据
              </h4>

              <div className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center">
                <Upload className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-900 mb-2">上传用户数据文件</h3>
                <p className="text-gray-600 mb-4">支持 CSV 格式文件，最多可导入 1000 个用户</p>

                <label className="inline-block">
                  <input
                    type="file"
                    accept=".csv"
                    onChange={handleFileUpload}
                    className="hidden"
                  />
                  <Button asChild className="cursor-pointer">
                    <span>选择文件</span>
                  </Button>
                </label>
              </div>

              {/* 格式说明 */}
              <div className="mt-4 p-4 bg-blue-50 rounded-lg">
                <h5 className="text-sm font-medium text-blue-800 mb-2">文件格式要求：</h5>
                <ul className="text-xs text-blue-700 space-y-1">
                  <li>• 文件格式：CSV (逗号分隔值)</li>
                  <li>• 必需字段：username（用户名）, email（邮箱）</li>
                  <li>• 可选字段：fullName（姓名）, role（角色：admin/operator/viewer）, password（密码）</li>
                  <li>• 第一行必须为字段标题行</li>
                  <li>• 如不填写密码，系统将自动生成</li>
                </ul>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* 预览步骤 */}
      {step === 'preview' && (
        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <h4 className="text-lg font-medium">数据预览</h4>
            <div className="flex items-center space-x-4 text-sm">
              <span className="text-green-600">
                <CheckCircle className="w-4 h-4 inline mr-1" />
                有效: {validUsers.length}
              </span>
              {invalidUsers.length > 0 && (
                <span className="text-red-600">
                  <AlertTriangle className="w-4 h-4 inline mr-1" />
                  无效: {invalidUsers.length}
                </span>
              )}
            </div>
          </div>

          {/* 有效用户列表 */}
          {validUsers.length > 0 && (
            <Card>
              <CardContent className="p-0">
                <div className="p-4 border-b">
                  <h5 className="font-medium text-green-700 flex items-center">
                    <CheckCircle className="w-4 h-4 mr-2" />
                    有效用户 ({validUsers.length})
                  </h5>
                </div>
                <div className="max-h-64 overflow-y-auto">
                  <Table
                    data={validUsers}
                    columns={[
                      {
                        key: 'username',
                        title: '用户名',
                        render: (user: ImportUser) => (
                          <div className="flex items-center">
                            <User className="w-4 h-4 mr-2 text-gray-400" />
                            {user.username}
                          </div>
                        )
                      },
                      {
                        key: 'email',
                        title: '邮箱',
                        render: (user: ImportUser) => (
                          <div className="flex items-center">
                            <Mail className="w-4 h-4 mr-2 text-gray-400" />
                            {user.email}
                          </div>
                        )
                      },
                      {
                        key: 'fullName',
                        title: '姓名',
                        render: (user: ImportUser) => user.fullName || '-'
                      },
                      {
                        key: 'role',
                        title: '角色',
                        render: (user: ImportUser) => (
                          <Badge className={getRoleColor(user.role)}>
                            {getRoleLabel(user.role)}
                          </Badge>
                        )
                      },
                      {
                        key: 'password',
                        title: '密码',
                        render: (user: ImportUser) => 
                          user.password ? '已设置' : '自动生成'
                      }
                    ]}
                  />
                </div>
              </CardContent>
            </Card>
          )}

          {/* 无效用户列表 */}
          {invalidUsers.length > 0 && (
            <Card>
              <CardContent className="p-0">
                <div className="p-4 border-b">
                  <h5 className="font-medium text-red-700 flex items-center">
                    <AlertTriangle className="w-4 h-4 mr-2" />
                    无效用户 ({invalidUsers.length})
                  </h5>
                </div>
                <div className="max-h-64 overflow-y-auto">
                  <Table
                    data={invalidUsers}
                    columns={[
                      {
                        key: 'username',
                        title: '用户名',
                        render: (user: ImportUser) => user.username || '-'
                      },
                      {
                        key: 'email',
                        title: '邮箱',
                        render: (user: ImportUser) => user.email || '-'
                      },
                      {
                        key: 'errors',
                        title: '错误信息',
                        render: (user: ImportUser) => (
                          <div className="space-y-1">
                            {user.errors?.map((error, index) => (
                              <div key={index} className="text-xs text-red-600 bg-red-50 px-2 py-1 rounded">
                                {error}
                              </div>
                            ))}
                          </div>
                        )
                      }
                    ]}
                  />
                </div>
              </CardContent>
            </Card>
          )}

          {/* 导入选项 */}
          <Card>
            <CardContent className="p-6">
              <h5 className="font-medium mb-4">导入选项</h5>
              <div className="space-y-3">
                <label className="flex items-center">
                  <input
                    type="checkbox"
                    checked={sendEmail}
                    onChange={(e) => setSendEmail(e.target.checked)}
                    className="rounded border-gray-300 mr-3"
                  />
                  <span>发送欢迎邮件给新用户</span>
                </label>
                <label className="flex items-center">
                  <input
                    type="checkbox"
                    checked={forcePasswordChange}
                    onChange={(e) => setForcePasswordChange(e.target.checked)}
                    className="rounded border-gray-300 mr-3"
                  />
                  <span>强制用户首次登录时修改密码</span>
                </label>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* 导入进行中 */}
      {step === 'importing' && (
        <Card>
          <CardContent className="p-8 text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
            <h4 className="text-lg font-medium mb-2">正在导入用户...</h4>
            <p className="text-gray-600 mb-4">请稍候，正在创建 {validUsers.length} 个用户账户</p>

            {/* 进度条 */}
            <div className="w-full bg-gray-200 rounded-full h-2 mb-2">
              <div 
                className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${importProgress}%` }}
              ></div>
            </div>
            <p className="text-sm text-gray-500">{importProgress}%</p>
          </CardContent>
        </Card>
      )}

      {/* 导入完成 */}
      {step === 'completed' && importResult && (
        <Card>
          <CardContent className="p-8 text-center">
            <CheckCircle className="w-16 h-16 text-green-600 mx-auto mb-4" />
            <h4 className="text-lg font-medium mb-2">导入完成！</h4>

            <div className="grid grid-cols-3 gap-4 mb-6 text-sm">
              <div className="bg-blue-50 p-3 rounded">
                <div className="font-medium text-blue-800">总计</div>
                <div className="text-2xl font-bold text-blue-600">{importResult.total}</div>
              </div>
              <div className="bg-green-50 p-3 rounded">
                <div className="font-medium text-green-800">成功</div>
                <div className="text-2xl font-bold text-green-600">{importResult.success}</div>
              </div>
              <div className="bg-red-50 p-3 rounded">
                <div className="font-medium text-red-800">失败</div>
                <div className="text-2xl font-bold text-red-600">{importResult.failed}</div>
              </div>
            </div>

            {importResult.errors?.length > 0 && (
              <div className="text-left bg-red-50 p-4 rounded-lg mb-4">
                <h5 className="font-medium text-red-800 mb-2">导入错误：</h5>
                <ul className="text-sm text-red-700 space-y-1">
                  {importResult.errors.map((error: any, index: number) => (
                    <li key={index}>
                      第 {error.row} 行：{error.error}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* 操作按钮 */}
      <div className="flex justify-end space-x-3 pt-6 border-t">
        <Button
          variant="outline"
          onClick={onCancel}
          disabled={step === 'importing'}
        >
          {step === 'completed' ? '关闭' : '取消'}
        </Button>

        {step === 'upload' && (
          <Button onClick={addManualUser}>
            手动添加用户
          </Button>
        )}

        {step === 'preview' && (
          <>
            <Button
              variant="outline"
              onClick={() => setStep('upload')}
            >
              重新上传
            </Button>
            <Button
              onClick={handleImport}
              disabled={validUsers.length === 0}
            >
              开始导入 ({validUsers.length})
            </Button>
          </>
        )}
      </div>
    </div>
  )
}

'use client'

import React, { useState } from 'react'
import { useForm, Controller } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { Eye, EyeOff, User, Mail, UserCheck, Shield } from 'lucide-react'
import {
  Button, SimpleInput as Input, SimpleSelect, SelectItem, Card, CardContent,
  Badge, Loading
} from '@/components/atoms'
import { User as UserType, UserRole, UserStatus } from '../types'

// 表单验证 Schema
const userFormSchema = z.object({
  username: z
    .string()
    .min(3, '用户名至少3个字符')
    .max(50, '用户名不能超过50个字符')
    .regex(/^[a-zA-Z0-9_-]+$/, '用户名只能包含字母、数字、下划线和连字符'),
  email: z
    .string()
    .email('请输入有效的邮箱地址'),
  fullName: z
    .string()
    .max(100, '姓名不能超过100个字符')
    .optional()
    .or(z.literal('')),
  role: z.enum(['admin', 'operator', 'viewer'] as const),
  status: z.enum(['active', 'inactive', 'locked', 'pending'] as const),
  password: z
    .string()
    .min(8, '密码至少8个字符')
    .regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/, 
      '密码必须包含大小写字母、数字和特殊字符')
    .optional(),
  confirmPassword: z.string().optional()
}).refine((data) => {
  if (data.password && data.confirmPassword) {
    return data.password === data.confirmPassword
  }
  return true
}, {
  message: '两次输入的密码不一致',
  path: ['confirmPassword']
})

type UserFormData = z.infer<typeof userFormSchema>

interface Props {
  initialData?: Partial<UserType>
  onSubmit: (data: UserFormData) => Promise<void>
  onCancel: () => void
  loading?: boolean
}

// 角色选项
const roleOptions = [
  { value: 'admin', label: '管理员', icon: Shield, color: 'text-red-600' },
  { value: 'operator', label: '操作员', icon: UserCheck, color: 'text-blue-600' },
  { value: 'viewer', label: '查看者', icon: User, color: 'text-gray-600' }
]

// 状态选项
const statusOptions = [
  { value: 'active', label: '激活', color: 'bg-green-100 text-green-800' },
  { value: 'inactive', label: '停用', color: 'bg-gray-100 text-gray-800' },
  { value: 'locked', label: '锁定', color: 'bg-red-100 text-red-800' },
  { value: 'pending', label: '待激活', color: 'bg-yellow-100 text-yellow-800' }
]

export const UserForm: React.FC<Props> = ({ 
  initialData, 
  onSubmit, 
  onCancel, 
  loading = false 
}) => {
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  const [submitting, setSubmitting] = useState(false)

  const isEditMode = !!initialData?.id

  // 表单配置
  const {
    control,
    handleSubmit,
    formState: { errors, isValid, isDirty },
    watch,
    setValue,
    clearErrors
  } = useForm<UserFormData>({
    resolver: zodResolver(userFormSchema),
    defaultValues: {
      username: initialData?.username || '',
      email: initialData?.email || '',
      fullName: initialData?.fullName || '',
      role: initialData?.role || 'viewer',
      status: initialData?.status || 'active',
      password: '',
      confirmPassword: ''
    },
    mode: 'onChange'
  })

  // 监听密码变化
  const password = watch('password')

  // 提交处理
  const handleFormSubmit = async (data: UserFormData) => {
    setSubmitting(true)
    try {
      // 如果是编辑模式且密码为空，则不传递密码字段
      if (isEditMode && !data.password) {
        const { password, confirmPassword, ...updateData } = data
        await onSubmit(updateData)
      } else {
        await onSubmit(data)
      }
    } catch (error) {
      console.error('提交表单失败:', error)
    } finally {
      setSubmitting(false)
    }
  }

  // 密码强度检查
  const getPasswordStrength = (pwd: string) => {
    if (!pwd) return { strength: 0, label: '', color: '' }

    let strength = 0
    const checks = [
      /[a-z]/.test(pwd), // 小写字母
      /[A-Z]/.test(pwd), // 大写字母
      /\d/.test(pwd), // 数字
      /[@$!%*?&]/.test(pwd), // 特殊字符
      pwd.length >= 8 // 长度
    ]

    strength = checks.filter(check => check).length

    if (strength <= 2) {
      return { strength, label: '弱', color: 'text-red-500' }
    } else if (strength <= 3) {
      return { strength, label: '中等', color: 'text-yellow-500' }
    } else {
      return { strength, label: '强', color: 'text-green-500' }
    }
  }

  const passwordStrength = getPasswordStrength(password || '')

  return (
    <form onSubmit={handleSubmit(handleFormSubmit)} className="space-y-6">
      {/* 基本信息 */}
      <Card>
        <CardContent className="p-6">
          <h4 className="text-lg font-medium mb-4 flex items-center">
            <User className="w-5 h-5 mr-2" />
            基本信息
          </h4>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* 用户名 */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                用户名 <span className="text-red-500">*</span>
              </label>
              <Controller
                name="username"
                control={control}
                render={({ field }) => (
                  <Input
                    {...field}
                    placeholder="输入用户名"
                    error={errors.username?.message}
                    disabled={isEditMode} // 编辑模式下用户名不可修改
                  />
                )}
              />
            </div>

            {/* 邮箱 */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                邮箱地址 <span className="text-red-500">*</span>
              </label>
              <Controller
                name="email"
                control={control}
                render={({ field }) => (
                  <Input
                    {...field}
                    type="email"
                    placeholder="输入邮箱地址"
                    leftIcon={<Mail className="w-4 h-4" />}
                    error={errors.email?.message}
                  />
                )}
              />
            </div>

            {/* 姓名 */}
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                真实姓名
              </label>
              <Controller
                name="fullName"
                control={control}
                render={({ field }) => (
                  <Input
                    {...field}
                    placeholder="输入真实姓名（可选）"
                    error={errors.fullName?.message}
                  />
                )}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* 角色和权限 */}
      <Card>
        <CardContent className="p-6">
          <h4 className="text-lg font-medium mb-4 flex items-center">
            <Shield className="w-5 h-5 mr-2" />
            角色和权限
          </h4>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* 角色选择 */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                用户角色 <span className="text-red-500">*</span>
              </label>
              <Controller
                name="role"
                control={control}
                render={({ field }) => (
                  <SimpleSelect
                    value={field.value}
                    onChange={field.onChange}
                    placeholder="选择角色"
                    error={errors.role?.message}
                  >
                    {roleOptions.map((option) => {
                      const IconComponent = option.icon
                      return (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      )
                    })}
                  </SimpleSelect>
                )}
              />
              {/* 角色说明 */}
              <div className="mt-2 text-xs text-gray-500">
                <p>• 管理员：拥有所有权限</p>
                <p>• 操作员：可以执行设备巡检操作</p>
                <p>• 查看者：只能查看数据，无法修改</p>
              </div>
            </div>

            {/* 状态选择 */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                账户状态 <span className="text-red-500">*</span>
              </label>
              <Controller
                name="status"
                control={control}
                render={({ field }) => (
                  <SimpleSelect
                    value={field.value}
                    onChange={field.onChange}
                    placeholder="选择状态"
                    error={errors.status?.message}
                  >
                    {statusOptions.map((option) => (
                      <SelectItem key={option.value} value={option.value}>
                        {option.label}
                      </SelectItem>
                    ))}
                  </SimpleSelect>
                )}
              />
              {/* 状态说明 */}
              <div className="mt-2">
                <Controller
                  name="status"
                  control={control}
                  render={({ field }) => {
                    const selectedOption = statusOptions.find(opt => opt.value === field.value)
                    return selectedOption ? (
                      <Badge className={selectedOption.color}>
                        {selectedOption.label}
                      </Badge>
                    ) : <div></div>
                  }}
                />
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* 密码设置 */}
      {(!isEditMode || password) && (
        <Card>
          <CardContent className="p-6">
            <h4 className="text-lg font-medium mb-4 flex items-center">
              <Eye className="w-5 h-5 mr-2" />
              {isEditMode ? '修改密码' : '设置密码'}
            </h4>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* 密码 */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  {isEditMode ? '新密码' : '密码'} 
                  {!isEditMode && <span className="text-red-500">*</span>}
                </label>
                <Controller
                  name="password"
                  control={control}
                  render={({ field }) => (
                    <div className="relative">
                      <Input
                        {...field}
                        type={showPassword ? 'text' : 'password'}
                        placeholder={isEditMode ? '留空则不修改密码' : '输入密码'}
                        error={errors.password?.message}
                        rightIcon={
                          <button
                            type="button"
                            onClick={() => setShowPassword(!showPassword)}
                            className="text-gray-400 hover:text-gray-600"
                          >
                            {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                          </button>
                        }
                      />
                    </div>
                  )}
                />
                {/* 密码强度指示器 */}
                {password && (
                  <div className="mt-2">
                    <div className="flex items-center justify-between text-xs">
                      <span>密码强度:</span>
                      <span className={passwordStrength.color}>
                        {passwordStrength.label}
                      </span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-1 mt-1">
                      <div 
                        className={`h-1 rounded-full transition-all duration-300 ${
                          passwordStrength.strength <= 2 ? 'bg-red-500' :
                          passwordStrength.strength <= 3 ? 'bg-yellow-500' : 'bg-green-500'
                        }`}
                        style={{ width: `${(passwordStrength.strength / 5) * 100}%` }}
                      />
                    </div>
                  </div>
                )}
              </div>

              {/* 确认密码 */}
              {password && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    确认密码 <span className="text-red-500">*</span>
                  </label>
                  <Controller
                    name="confirmPassword"
                    control={control}
                    render={({ field }) => (
                      <Input
                        {...field}
                        type={showConfirmPassword ? 'text' : 'password'}
                        placeholder="再次输入密码"
                        error={errors.confirmPassword?.message}
                        rightIcon={
                          <button
                            type="button"
                            onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                            className="text-gray-400 hover:text-gray-600"
                          >
                            {showConfirmPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                          </button>
                        }
                      />
                    )}
                  />
                </div>
              )}
            </div>

            {/* 密码要求说明 */}
            <div className="mt-4 p-3 bg-blue-50 rounded-lg">
              <h5 className="text-sm font-medium text-blue-800 mb-2">密码要求：</h5>
              <ul className="text-xs text-blue-700 space-y-1">
                <li>• 至少8个字符</li>
                <li>• 包含大写字母</li>
                <li>• 包含小写字母</li>
                <li>• 包含数字</li>
                <li>• 包含特殊字符 (@$!%*?&)</li>
              </ul>
            </div>
          </CardContent>
        </Card>
      )}

      {/* 操作按钮 */}
      <div className="flex justify-end space-x-3 pt-6 border-t">
        <Button
          type="button"
          variant="outline"
          onClick={onCancel}
          disabled={submitting}
        >
          取消
        </Button>
        <Button
          type="submit"
          disabled={!isValid || (!isDirty && isEditMode) || submitting}
          loading={submitting}
        >
          {isEditMode ? '保存修改' : '创建用户'}
        </Button>
      </div>
    </form>
  )
}

'use client'

import React, { useState, useEffect, useCallback } from 'react'
import {
  Users, Plus, UserPlus, Search, Filter, MoreHorizontal,
  Edit, Trash2, Lock, Unlock, UserX, Eye, Download,
  Mail, Phone, Calendar, MapPin, Shield, Activity
} from 'lucide-react'
import {
  Card, CardHeader, CardTitle, CardContent, Button,
  SimpleInput as Input, SimpleSelect, SelectItem, Table, SimpleModal, Badge
} from '@/components/atoms'
import { useUsers } from '../hooks/useUsers'
import { UserForm } from './UserForm'
import { UserBulkImport } from './UserBulkImport'
import { User, UserRole, UserStatus } from '../types'

interface Props {
  searchText: string
}

// 角色标签颜色映射
const roleColors: Record<UserRole, string> = {
  admin: 'bg-red-100 text-red-800',
  operator: 'bg-blue-100 text-blue-800',
  viewer: 'bg-gray-100 text-gray-800'
}

// 状态标签颜色映射
const statusColors: Record<UserStatus, string> = {
  active: 'bg-green-100 text-green-800',
  inactive: 'bg-gray-100 text-gray-800', 
  locked: 'bg-red-100 text-red-800',
  pending: 'bg-yellow-100 text-yellow-800'
}

// 角色显示名称
const roleLabels: Record<UserRole, string> = {
  admin: '管理员',
  operator: '操作员',
  viewer: '查看者'
}

// 状态显示名称
const statusLabels: Record<UserStatus, string> = {
  active: '活跃',
  inactive: '停用',
  locked: '锁定', 
  pending: '待激活'
}

export const UserManagement: React.FC<Props> = ({ searchText }) => {
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize] = useState(20)
  const [searchQuery, setSearchQuery] = useState('')
  const [roleFilter, setRoleFilter] = useState<UserRole | ''>("")
  const [statusFilter, setStatusFilter] = useState<UserStatus | ''>("")
  const [sortBy, setSortBy] = useState('created_at')
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc')

  // Modal states
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false)
  const [isEditModalOpen, setIsEditModalOpen] = useState(false)
  const [isImportModalOpen, setIsImportModalOpen] = useState(false)
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false)
  const [selectedUser, setSelectedUser] = useState<User | null>(null)
  const [selectedUsers, setSelectedUsers] = useState<string[]>([])

  // 使用自定义 Hook
  const {
    users,
    loading,
    total,
    hasNext,
    hasPrev,
    error,
    createUser,
    updateUser,
    deleteUser,
    bulkOperation,
    importUsers,
    refetch
  } = useUsers({
    page: currentPage,
    pageSize,
    search: searchQuery,
    role: roleFilter || undefined,
    status: statusFilter || undefined,
    sortBy,
    sortOrder
  })

  // 搜索防抖
  useEffect(() => {
    const timer = setTimeout(() => {
      setSearchQuery(searchText)
      setCurrentPage(1)
    }, 300)

    return () => clearTimeout(timer)
  }, [searchText])

  // 处理筛选变化
  const handleFilterChange = useCallback((key: string, value: string) => {
    if (key === 'role') {
      setRoleFilter(value as UserRole | '')
    } else if (key === 'status') {
      setStatusFilter(value as UserStatus | '')
    }
    setCurrentPage(1)
  }, [])

  // 处理排序变化
  const handleSort = useCallback((field: string) => {
    if (sortBy === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')
    } else {
      setSortBy(field)
      setSortOrder('desc')
    }
    setCurrentPage(1)
  }, [sortBy, sortOrder])

  // 处理用户选择
  const handleUserSelect = useCallback((userId: string, selected: boolean) => {
    setSelectedUsers(prev => 
      selected 
        ? [...prev, userId]
        : prev.filter(id => id !== userId)
    )
  }, [])

  // 处理全选
  const handleSelectAll = useCallback((selected: boolean) => {
    setSelectedUsers(selected ? users.map(user => user.id) : [])
  }, [users])

  // 处理用户操作
  const handleUserAction = useCallback(async (action: string, user?: User) => {
    try {
      switch (action) {
        case 'edit':
          setSelectedUser(user || null)
          setIsEditModalOpen(true)
          break
        case 'delete':
          setSelectedUser(user || null)
          setIsDeleteModalOpen(true)
          break
        case 'lock':
          if (user) {
            await updateUser(user.id, { status: 'locked' })
          }
          break
        case 'unlock':
          if (user) {
            await updateUser(user.id, { status: 'active' })
          }
          break
        default:
          break
      }
    } catch (error) {
      console.error('操作失败:', error)
    }
  }, [updateUser])

  // 处理批量操作
  const handleBulkAction = useCallback(async (action: string) => {
    if (selectedUsers.length === 0) return

    try {
      await bulkOperation({
        userIds: selectedUsers,
        type: action as any
      })
      setSelectedUsers([])
    } catch (error) {
      console.error('批量操作失败:', error)
    }
  }, [selectedUsers, bulkOperation])

  // 格式化日期
  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  if (error) {
    return (
      <div className="text-center py-8">
        <p className="text-red-600">加载用户列表失败：{error}</p>
        <Button onClick={refetch} className="mt-4">重试</Button>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* 页头 */}
      <div className="flex justify-between items-center">
        <div>
          <h3 className="text-lg font-semibold">用户管理</h3>
          <p className="text-sm text-gray-600">管理系统用户账户和权限</p>
        </div>
        <div className="flex gap-2">
          <Button 
            variant="outline" 
            onClick={() => setIsImportModalOpen(true)}
          >
            <UserPlus className="w-4 h-4 mr-2" />
            批量导入
          </Button>
          <Button onClick={() => setIsCreateModalOpen(true)}>
            <Plus className="w-4 h-4 mr-2" />
            添加用户
          </Button>
        </div>
      </div>

      {/* 筛选栏 */}
      <Card>
        <CardContent className="p-4">
          <div className="flex flex-wrap gap-4 items-center">
            {/* 搜索框 */}
            <div className="flex-1 min-w-64">
              <Input
                placeholder="搜索用户名、邮箱或姓名..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>

            {/* 角色筛选 */}
            <SimpleSelect
              value={roleFilter}
              onChange={(value) => handleFilterChange('role', value)}
              placeholder="所有角色"
            >
              <SelectItem value="">所有角色</SelectItem>
              <SelectItem value="admin">管理员</SelectItem>
              <SelectItem value="operator">操作员</SelectItem>
              <SelectItem value="viewer">查看者</SelectItem>
            </SimpleSelect>

            {/* 状态筛选 */}
            <SimpleSelect
              value={statusFilter}
              onChange={(value) => handleFilterChange('status', value)}
              placeholder="所有状态"
            >
              <SelectItem value="">所有状态</SelectItem>
              <SelectItem value="active">活跃</SelectItem>
              <SelectItem value="inactive">停用</SelectItem>
              <SelectItem value="locked">锁定</SelectItem>
              <SelectItem value="pending">待激活</SelectItem>
            </SimpleSelect>

            {/* 批量操作 */}
            {selectedUsers.length > 0 && (
              <div className="flex gap-2">
                <Button 
                  variant="outline" 
                  size="sm"
                  onClick={() => handleBulkAction('activate')}
                >
                  激活 ({selectedUsers.length})
                </Button>
                <Button 
                  variant="outline" 
                  size="sm"
                  onClick={() => handleBulkAction('deactivate')}
                >
                  停用 ({selectedUsers.length})
                </Button>
                <Button 
                  variant="destructive" 
                  size="sm"
                  onClick={() => handleBulkAction('delete')}
                >
                  删除 ({selectedUsers.length})
                </Button>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* 用户表格 */}
      <Card>
        <Table
          loading={loading}
          data={users}
          columns={[
            {
              key: 'select',
              title: '',
              render: (value: any, user: User) => (
                <input
                  type="checkbox"
                  checked={selectedUsers.includes(user.id)}
                  onChange={(e) => handleUserSelect(user.id, e.target.checked)}
                  className="rounded border-gray-300"
                />
              ),
              width: '48px'
            },
            {
              key: 'user',
              title: '用户信息',
              sortable: true,
              render: (value: any, user: User) => (
                <div className="flex items-center space-x-3">
                  <div className="flex-shrink-0">
                    <div className="w-10 h-10 rounded-full bg-gray-100 flex items-center justify-center">
                      <Users className="w-5 h-5 text-gray-600" />
                    </div>
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium text-gray-900">
                      {user.fullName || user.username}
                    </p>
                    <p className="text-sm text-gray-500">{user.email}</p>
                    {user.lastLoginAt && (
                      <p className="text-xs text-gray-400">
                        最后登录: {formatDate(user.lastLoginAt)}
                      </p>
                    )}
                  </div>
                </div>
              )
            },
            {
              key: 'role',
              title: '角色',
              sortable: true,
              render: (value: any, user: User) => (
                <Badge className={roleColors[user.role]}>
                  {roleLabels[user.role]}
                </Badge>
              )
            },
            {
              key: 'status',
              title: '状态',
              sortable: true,
              render: (value: any, user: User) => (
                <Badge className={statusColors[user.status]}>
                  {statusLabels[user.status]}
                </Badge>
              )
            },
            {
              key: 'createdAt',
              title: '创建时间',
              sortable: true,
              render: (value: any, user: User) => (
                <span className="text-sm text-gray-900">
                  {formatDate(user.createdAt)}
                </span>
              )
            },
            {
              key: 'actions',
              title: '操作',
              render: (value: any, user: User) => (
                <div className="flex items-center space-x-2">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleUserAction('edit', user)}
                  >
                    <Edit className="w-4 h-4" />
                  </Button>
                  {user.status === 'active' ? (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleUserAction('lock', user)}
                    >
                      <Lock className="w-4 h-4" />
                    </Button>
                  ) : (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleUserAction('unlock', user)}
                    >
                      <Unlock className="w-4 h-4" />
                    </Button>
                  )}
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleUserAction('delete', user)}
                    className="text-red-600 hover:text-red-700"
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              ),
              width: '120px'
            }
          ]}
          pagination={{
            current: currentPage,
            total,
            pageSize,
            onChange: setCurrentPage,
            showTotal: true
          }}
        />
      </Card>

      {/* 创建用户模态框 */}
      <SimpleModal
        open={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        title="创建用户"
        size="md"
      >
        <UserForm
          onSubmit={async (userData) => {
            await createUser(userData)
            setIsCreateModalOpen(false)
          }}
          onCancel={() => setIsCreateModalOpen(false)}
        />
      </SimpleModal>

      {/* 编辑用户模态框 */}
      <SimpleModal
        open={isEditModalOpen}
        onClose={() => setIsEditModalOpen(false)}
        title="编辑用户"
        size="md"
      >
        {selectedUser && (
          <UserForm
            initialData={selectedUser}
            onSubmit={async (userData) => {
              await updateUser(selectedUser.id, userData)
              setIsEditModalOpen(false)
              setSelectedUser(null)
            }}
            onCancel={() => {
              setIsEditModalOpen(false)
              setSelectedUser(null)
            }}
          />
        )}
      </SimpleModal>

      {/* 批量导入模态框 */}
      <SimpleModal
        open={isImportModalOpen}
        onClose={() => setIsImportModalOpen(false)}
        title="批量导入用户"
        size="lg"
      >
        <UserBulkImport
          onSubmit={async (importData) => {
            await importUsers(importData)
            setIsImportModalOpen(false)
          }}
          onCancel={() => setIsImportModalOpen(false)}
        />
      </SimpleModal>

      {/* 删除确认模态框 */}
      <SimpleModal
        open={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title="确认删除"
        size="sm"
      >
        {selectedUser && (
          <div className="space-y-4">
            <p>您确定要删除用户 <strong>{selectedUser.username}</strong> 吗？</p>
            <p className="text-sm text-gray-600">此操作无法撤销。</p>
            <div className="flex justify-end space-x-2">
              <Button
                variant="outline"
                onClick={() => {
                  setIsDeleteModalOpen(false)
                  setSelectedUser(null)
                }}
              >
                取消
              </Button>
              <Button
                variant="destructive"
                onClick={async () => {
                  await deleteUser(selectedUser.id)
                  setIsDeleteModalOpen(false)
                  setSelectedUser(null)
                }}
              >
                确认删除
              </Button>
            </div>
          </div>
        )}
      </SimpleModal>
    </div>
  )
}

