// 状态管理Hooks
export const useSettingsFilters = () => {
  const [filters, setFilters] = useState({
    userRole: 'all' as 'all' | string,
    userStatus: 'all' as 'all' | 'active' | 'inactive' | 'locked' | 'pending',
    logAction: 'all' as 'all' | string,
    logStatus: 'all' as 'all' | 'success' | 'failed' | 'error',
    dateRange: {
      start: '',
      end: '',
    },
    searchText: '',
  })

  const updateFilter = useCallback((key: string, value: any) => {
    setFilters(prev => ({
      ...prev,
      [key]: value,
    }))
  }, [])

  const resetFilters = useCallback(() => {
    setFilters({
      userRole: 'all',
      userStatus: 'all',
      logAction: 'all',
      logStatus: 'all',
      dateRange: { start: '', end: '' },
      searchText: '',
    })
  }, [])

  return {
    filters,
    updateFilter,
    resetFilters,
  }
}

// 设置编辑状态管理
export const useSettingsEditor = () => {
  const [editingConfig, setEditingConfig] = useState<string | null>(null)
  const [pendingChanges, setPendingChanges] = useState<Record<string, any>>({})

  const startEditing = useCallback((configKey: string) => {
    setEditingConfig(configKey)
  }, [])

  const stopEditing = useCallback(() => {
    setEditingConfig(null)
    setPendingChanges({})
  }, [])

  const updatePendingChange = useCallback((key: string, value: any) => {
    setPendingChanges(prev => ({
      ...prev,
      [key]: value,
    }))
  }, [])

  const hasPendingChanges = Object.keys(pendingChanges).length > 0

  return {
    editingConfig,
    pendingChanges,
    hasPendingChanges,
    startEditing,
    stopEditing,
    updatePendingChange,
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { userManagementApi } from '../api/settings.api'
import { 
  User, UserQueryParams, UserUpdate, 
  UserBulkOperation, UserBulkImport 
} from '../types'

interface UseUsersParams extends Partial<UserQueryParams> {}

interface UseUsersResult {
  // 数据状态
  users: User[]
  loading: boolean
  error: string | null
  total: number
  hasNext: boolean
  hasPrev: boolean

  // 操作方法
  createUser: (userData: any) => Promise<void>
  updateUser: (id: string, userData: UserUpdate) => Promise<void>
  deleteUser: (id: string) => Promise<void>
  bulkOperation: (operation: UserBulkOperation) => Promise<void>
  importUsers: (importData: UserBulkImport) => Promise<void>
  refetch: () => void
}

// 查询键常量
const QUERY_KEYS = {
  users: (params: UseUsersParams) => ['users', params],
  userDetail: (id: string) => ['users', id],
  userPermissions: (id: string) => ['users', id, 'permissions'],
  statistics: () => ['users', 'statistics']
} as const

export const useUsers = (params: UseUsersParams = {}): UseUsersResult => {
  const [error, setError] = useState<string | null>(null)
  const queryClient = useQueryClient()

  // 构建查询参数
  const queryParams: UserQueryParams = {
    page: params.page || 1,
    pageSize: params.pageSize || 20,
    search: params.search,
    role: params.role,
    status: params.status,
    sortBy: params.sortBy || 'created_at',
    sortOrder: params.sortOrder || 'desc'
  }

  // 获取用户列表
  const {
    data: userListData,
    isLoading,
    error: queryError,
    refetch
  } = useQuery({
    queryKey: QUERY_KEYS.users(queryParams),
    queryFn: () => userManagementApi.getUsers(queryParams),
    staleTime: 5 * 60 * 1000, // 5分钟
    gcTime: 10 * 60 * 1000, // 10分钟
    retry: 2,
    retryDelay: 1000
  })

  // 创建用户
  const createUserMutation = useMutation({
    mutationFn: userManagementApi.createUser,
    onSuccess: () => {
      // 无效化相关查询缓存
      queryClient.invalidateQueries({ queryKey: ['users'] })
      setError(null)
    },
    onError: (error: any) => {
      setError(error.response?.data?.message || '创建用户失败')
    }
  })

  // 更新用户
  const updateUserMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: UserUpdate }) => 
      userManagementApi.updateUser(id, data),
    onSuccess: (updatedUser) => {
      // 更新查询缓存
      queryClient.setQueryData(
        QUERY_KEYS.userDetail(updatedUser.id), 
        updatedUser
      )
      // 无效化用户列表缓存
      queryClient.invalidateQueries({ queryKey: ['users'] })
      setError(null)
    },
    onError: (error: any) => {
      setError(error.response?.data?.message || '更新用户失败')
    }
  })

  // 删除用户
  const deleteUserMutation = useMutation({
    mutationFn: userManagementApi.deleteUser,
    onSuccess: (_, deletedId) => {
      // 从缓存中移除用户数据
      queryClient.removeQueries({ queryKey: QUERY_KEYS.userDetail(deletedId) })
      // 无效化用户列表缓存
      queryClient.invalidateQueries({ queryKey: ['users'] })
      setError(null)
    },
    onError: (error: any) => {
      setError(error.response?.data?.message || '删除用户失败')
    }
  })

  // 批量操作
  const bulkOperationMutation = useMutation({
    mutationFn: userManagementApi.bulkOperation,
    onSuccess: () => {
      // 无效化所有用户相关缓存
      queryClient.invalidateQueries({ queryKey: ['users'] })
      setError(null)
    },
    onError: (error: any) => {
      setError(error.response?.data?.message || '批量操作失败')
    }
  })

  // 批量导入用户
  const importUsersMutation = useMutation({
    mutationFn: userManagementApi.importUsers,
    onSuccess: () => {
      // 无效化所有用户相关缓存
      queryClient.invalidateQueries({ queryKey: ['users'] })
      setError(null)
    },
    onError: (error: any) => {
      setError(error.response?.data?.message || '用户导入失败')
    }
  })

  // 包装操作方法
  const createUser = useCallback(async (userData: any) => {
    try {
      await createUserMutation.mutateAsync(userData)
    } catch (error) {
      throw error
    }
  }, [createUserMutation])

  const updateUser = useCallback(async (id: string, userData: UserUpdate) => {
    try {
      await updateUserMutation.mutateAsync({ id, data: userData })
    } catch (error) {
      throw error
    }
  }, [updateUserMutation])

  const deleteUser = useCallback(async (id: string) => {
    try {
      await deleteUserMutation.mutateAsync(id)
    } catch (error) {
      throw error
    }
  }, [deleteUserMutation])

  const bulkOperation = useCallback(async (operation: UserBulkOperation) => {
    try {
      await bulkOperationMutation.mutateAsync(operation)
    } catch (error) {
      throw error
    }
  }, [bulkOperationMutation])

  const importUsers = useCallback(async (importData: UserBulkImport) => {
    try {
      await importUsersMutation.mutateAsync(importData)
    } catch (error) {
      throw error
    }
  }, [importUsersMutation])

  // 处理错误
  useEffect(() => {
    if (queryError) {
      setError(queryError.message || '获取用户列表失败')
    }
  }, [queryError])

  return {
    // 数据状态
    users: userListData?.items || [],
    loading: isLoading,
    error,
    total: userListData?.total || 0,
    hasNext: userListData?.hasNext || false,
    hasPrev: userListData?.hasPrev || false,

    // 操作方法
    createUser,
    updateUser,
    deleteUser,
    bulkOperation,
    importUsers,
    refetch
  }
}

