  AlertTriangle,
  TrendingUp,
  TrendingDown,
  Wifi,
  Server,
  Eye,
  EyeOff,
  Settings,
  RefreshCw,
  Filter,
  Download
} from 'lucide-react'
import {
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  Button,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Badge,
  Loading,
  Input
} from '@/components/atoms'
import { useTrafficAnalysis, useTrafficRealtime, useTrafficFilter } from '../hooks/useTrafficAnalysis'
import { TrafficViewMode } from '../types'
import { TrafficRealtimeChart } from './TrafficRealtimeChart'
import { TrafficTrendsChart } from './TrafficTrendsChart'
import { TrafficAnomaliesPanel } from './TrafficAnomaliesPanel'
import { TrafficSummaryCards } from './TrafficSummaryCards'

interface TrafficAnalysisViewProps {
  deviceIps?: string[]
}

export const TrafficAnalysisView: React.FC<TrafficAnalysisViewProps> = ({
  deviceIps = []
}) => {
  const [viewMode, setViewMode] = useState<TrafficViewMode>('summary')
  const [selectedDevices, setSelectedDevices] = useState<string[]>(deviceIps)
  const [isMonitoringActive, setIsMonitoringActive] = useState(false)
  const [refreshInterval, setRefreshInterval] = useState(30)

  const { 
    isLoading, 
    error, 
    getTrafficSummary,
    startMonitoring 
  } = useTrafficAnalysis()

  const {
    trafficData,
    isActive: realtimeActive,
    startRealtime,
    stopRealtime
  } = useTrafficRealtime(selectedDevices, refreshInterval * 1000)

  const { filter, updateFilter, resetFilter } = useTrafficFilter()

  const handleStartMonitoring = async () => {
    try {
      await startMonitoring({
        device_ips: selectedDevices,
        analysis_period_hours: 24,
        enable_anomaly_detection: true
      })
      setIsMonitoringActive(true)
      startRealtime()
    } catch (error) {
      console.error('Failed to start monitoring:', error)
    }
  }

  const handleStopMonitoring = () => {
    setIsMonitoringActive(false)
    stopRealtime()
  }

  const handleDeviceSelection = (deviceIp: string, selected: boolean) => {
    if (selected) {
      setSelectedDevices(prev => [...prev, deviceIp])
    } else {
      setSelectedDevices(prev => prev.filter(ip => ip !== deviceIp))
    }
  }

  const renderViewModeContent = () => {
    switch (viewMode) {
      case 'realtime':
        return (
          <TrafficRealtimeChart 
            trafficData={trafficData}
            isActive={realtimeActive}
          />
        )
      case 'trends':
        return (
          <TrafficTrendsChart 
            deviceIps={selectedDevices}
            timeRange={filter.time_range}
          />
        )
      case 'anomalies':
        return (
          <TrafficAnomaliesPanel 
            deviceIps={selectedDevices}
            filter={filter}
          />
        )
      case 'summary':
      default:
        return (
          <TrafficSummaryCards 
            deviceIps={selectedDevices}
          />
        )
    }
  }

  return (
    <div className="space-y-6">
      {/* 顶部控制栏 */}
      <Card>
        <CardContent className="p-4">
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
            {/* 左侧：视图切换 */}
            <div className="flex items-center gap-2">
              <div className="flex rounded-lg border p-1">
                {([
                  { key: 'summary', label: '概览', icon: Activity },
                  { key: 'realtime', label: '实时', icon: Wifi },
                  { key: 'trends', label: '趋势', icon: TrendingUp },
                  { key: 'anomalies', label: '异常', icon: AlertTriangle }
                ] as const).map(({ key, label, icon: Icon }) => (
                  <Button
                    key={key}
                    variant={viewMode === key ? 'default' : 'ghost'}
                    size="sm"
                    onClick={() => setViewMode(key)}
                    className="flex items-center gap-2"
                  >
                    <Icon className="h-4 w-4" />
                    {label}
                  </Button>
                ))}
              </div>
            </div>

            {/* 右侧：控制按钮 */}
            <div className="flex items-center gap-2">
              {/* 监控开关 */}
              <Button
                variant={isMonitoringActive ? 'default' : 'outline'}
                size="sm"
                onClick={isMonitoringActive ? handleStopMonitoring : handleStartMonitoring}
                disabled={selectedDevices.length === 0}
                className="flex items-center gap-2"
              >
                {isMonitoringActive ? (
                  <>
                    <EyeOff className="h-4 w-4" />
                    停止监控
                  </>
                ) : (
                  <>
                    <Eye className="h-4 w-4" />
                    开始监控
                  </>
                )}
              </Button>

              {/* 刷新间隔设置 */}
              <Select
                value={refreshInterval.toString()}
                onValueChange={(value) => setRefreshInterval(parseInt(value))}
              >
                <SelectTrigger className="w-32">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="10">10秒</SelectItem>
                  <SelectItem value="30">30秒</SelectItem>
                  <SelectItem value="60">1分钟</SelectItem>
                  <SelectItem value="300">5分钟</SelectItem>
                </SelectContent>
              </Select>

              {/* 设置按钮 */}
              <Button variant="outline" size="sm">
                <Settings className="h-4 w-4" />
              </Button>
            </div>
          </div>

          {/* 设备选择器 */}
          <div className="mt-4 pt-4 border-t">
            <div className="flex items-center justify-between mb-2">
              <h4 className="text-sm font-medium text-gray-700">监控设备</h4>
              <Badge variant="outline">
                {selectedDevices.length} 个设备
              </Badge>
            </div>

            {/* 设备列表 */}
            <div className="flex flex-wrap gap-2">
              {deviceIps.map(deviceIp => (
                <motion.div
                  key={deviceIp}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                >
                  <Badge
                    variant={selectedDevices.includes(deviceIp) ? 'default' : 'outline'}
                    className={`cursor-pointer transition-colors ${
                      selectedDevices.includes(deviceIp) 
                        ? 'bg-blue-600 hover:bg-blue-700' 
                        : 'hover:bg-gray-100'
                    }`}
                    onClick={() => handleDeviceSelection(
                      deviceIp, 
                      !selectedDevices.includes(deviceIp)
                    )}
                  >
                    <Server className="h-3 w-3 mr-1" />
                    {deviceIp}
                  </Badge>
                </motion.div>
              ))}

              {deviceIps.length === 0 && (
                <div className="text-sm text-gray-500 py-2">
                  暂无可监控的设备
                </div>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* 状态指示器 */}
      {(isMonitoringActive || isLoading) && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center gap-4 p-4 bg-blue-50 rounded-lg border border-blue-200"
        >
          {isLoading && <Loading size="sm" />}
          <div className="flex items-center gap-2">
            <div className={`w-2 h-2 rounded-full ${
              isMonitoringActive ? 'bg-green-500 animate-pulse' : 'bg-gray-400'
            }`} />
            <span className="text-sm font-medium text-blue-900">
              {isMonitoringActive ? '流量监控进行中' : '监控已暂停'}
            </span>
          </div>

          {realtimeActive && (
            <div className="flex items-center gap-2 text-sm text-blue-700">
              <RefreshCw className="h-4 w-4 animate-spin" />
              每 {refreshInterval} 秒刷新
            </div>
          )}
        </motion.div>
      )}

      {/* 错误提示 */}
      {error && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="p-4 bg-red-50 border border-red-200 rounded-lg"
        >
          <div className="flex items-center gap-2 text-red-800">
            <AlertTriangle className="h-4 w-4" />
            <span className="font-medium">错误</span>
          </div>
          <p className="text-sm text-red-700 mt-1">{error}</p>
        </motion.div>
      )}

      {/* 主内容区域 */}
      <motion.div
        key={viewMode}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
      >
        {renderViewModeContent()}
      </motion.div>
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  AlertTriangle,
  TrendingUp,
  TrendingDown,
  Zap,
  AlertCircle,
  Clock,
  Filter,
  RefreshCw,
  Eye,
  Settings
} from 'lucide-react'
import {
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  Button,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Badge,
  Loading,
  Input
} from '@/components/atoms'
import { useTrafficAnalysis } from '../hooks/useTrafficAnalysis'
import { TrafficAnomaly, TrafficFilter } from '../types'
import { formatDate, formatBytes } from '@/utils/formatters'

interface TrafficAnomaliesPanelProps {
  deviceIps: string[]
  filter: TrafficFilter
}

const ANOMALY_TYPE_CONFIG = {
  traffic_spike: {
    icon: TrendingUp,
    label: '流量激增',
    color: 'bg-orange-100 text-orange-800 border-orange-200'
  },
  traffic_drop: {
    icon: TrendingDown,
    label: '流量骤降',
    color: 'bg-blue-100 text-blue-800 border-blue-200'
  },
  high_utilization: {
    icon: Zap,
    label: '高利用率',
    color: 'bg-red-100 text-red-800 border-red-200'
  },
  high_errors: {
    icon: AlertCircle,
    label: '高错误率',
    color: 'bg-purple-100 text-purple-800 border-purple-200'
  }
}

const SEVERITY_CONFIG = {
  low: { color: 'bg-gray-100 text-gray-800', label: '低' },
  medium: { color: 'bg-yellow-100 text-yellow-800', label: '中' },
  high: { color: 'bg-orange-100 text-orange-800', label: '高' },
  critical: { color: 'bg-red-100 text-red-800', label: '严重' }
}

export const TrafficAnomaliesPanel: React.FC<TrafficAnomaliesPanelProps> = ({
  deviceIps,
  filter
}) => {
  const [anomalies, setAnomalies] = useState<TrafficAnomaly[]>([])
  const [filteredAnomalies, setFilteredAnomalies] = useState<TrafficAnomaly[]>([])
  const [severityFilter, setSeverityFilter] = useState<string>('')
  const [typeFilter, setTypeFilter] = useState<string>('')
  const [deviceFilter, setDeviceFilter] = useState<string>('')
  const [autoRefresh, setAutoRefresh] = useState(false)
  const [refreshInterval, setRefreshInterval] = useState(30)

  const { isLoading, error, getTrafficAnomalies } = useTrafficAnalysis()

  // 加载异常数据
  const loadAnomalies = async () => {
    try {
      const anomalyData = await getTrafficAnomalies(
        deviceFilter || undefined,
        severityFilter || undefined,
        24
      )
      setAnomalies(anomalyData)
    } catch (error) {
      console.error('Failed to load anomalies:', error)
    }
  }

  // 应用过滤器
  useEffect(() => {
    let filtered = [...anomalies]

    // 设备过滤
    if (deviceIps.length > 0) {
      filtered = filtered.filter(anomaly => 
        deviceIps.includes(anomaly.device_ip)
      )
    }

    // 严重程度过滤
    if (severityFilter) {
      filtered = filtered.filter(anomaly => 
        anomaly.severity === severityFilter
      )
    }

    // 类型过滤
    if (typeFilter) {
      filtered = filtered.filter(anomaly => 
        anomaly.anomaly_type === typeFilter
      )
    }

    // 设备IP过滤
    if (deviceFilter) {
      filtered = filtered.filter(anomaly => 
        anomaly.device_ip.includes(deviceFilter)
      )
    }

    setFilteredAnomalies(filtered)
  }, [anomalies, deviceIps, severityFilter, typeFilter, deviceFilter])

  // 自动刷新
  useEffect(() => {
    if (!autoRefresh) return

    const interval = setInterval(loadAnomalies, refreshInterval * 1000)
    return () => clearInterval(interval)
  }, [autoRefresh, refreshInterval])

  // 初始加载
  useEffect(() => {
    loadAnomalies()
  }, [])

  // 统计数据
  const stats = {
    total: filteredAnomalies.length,
    critical: filteredAnomalies.filter(a => a.severity === 'critical').length,
    high: filteredAnomalies.filter(a => a.severity === 'high').length,
    medium: filteredAnomalies.filter(a => a.severity === 'medium').length,
    low: filteredAnomalies.filter(a => a.severity === 'low').length,
    recent: filteredAnomalies.filter(a => 
      new Date(a.timestamp) > new Date(Date.now() - 60 * 60 * 1000)
    ).length
  }

  const renderStatsCards = () => (
    <div className="grid grid-cols-2 lg:grid-cols-6 gap-4 mb-6">
      <Card>
        <CardContent className="p-4 text-center">
          <div className="text-2xl font-bold text-blue-600">{stats.total}</div>
          <div className="text-xs text-gray-600">总异常</div>
        </CardContent>
      </Card>
      <Card>
        <CardContent className="p-4 text-center">
          <div className="text-2xl font-bold text-red-600">{stats.critical}</div>
          <div className="text-xs text-gray-600">严重</div>
        </CardContent>
      </Card>
      <Card>
        <CardContent className="p-4 text-center">
          <div className="text-2xl font-bold text-orange-600">{stats.high}</div>
          <div className="text-xs text-gray-600">高</div>
        </CardContent>
      </Card>
      <Card>
        <CardContent className="p-4 text-center">
          <div className="text-2xl font-bold text-yellow-600">{stats.medium}</div>
          <div className="text-xs text-gray-600">中</div>
        </CardContent>
      </Card>
      <Card>
        <CardContent className="p-4 text-center">
          <div className="text-2xl font-bold text-gray-600">{stats.low}</div>
          <div className="text-xs text-gray-600">低</div>
        </CardContent>
      </Card>
      <Card>
        <CardContent className="p-4 text-center">
          <div className="text-2xl font-bold text-green-600">{stats.recent}</div>
          <div className="text-xs text-gray-600">近1小时</div>
        </CardContent>
      </Card>
    </div>
  )

  const renderFilters = () => (
    <Card className="mb-6">
      <CardContent className="p-4">
        <div className="flex flex-col lg:flex-row gap-4 items-start lg:items-center justify-between">
          <div className="flex flex-wrap gap-3">
            {/* 严重程度过滤 */}
            <Select value={severityFilter} onValueChange={setSeverityFilter}>
              <SelectTrigger className="w-32">
                <SelectValue placeholder="严重程度" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="">全部</SelectItem>
                <SelectItem value="critical">严重</SelectItem>
                <SelectItem value="high">高</SelectItem>
                <SelectItem value="medium">中</SelectItem>
                <SelectItem value="low">低</SelectItem>
              </SelectContent>
            </Select>

            {/* 异常类型过滤 */}
            <Select value={typeFilter} onValueChange={setTypeFilter}>
              <SelectTrigger className="w-36">
                <SelectValue placeholder="异常类型" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="">全部类型</SelectItem>
                <SelectItem value="traffic_spike">流量激增</SelectItem>
                <SelectItem value="traffic_drop">流量骤降</SelectItem>
                <SelectItem value="high_utilization">高利用率</SelectItem>
                <SelectItem value="high_errors">高错误率</SelectItem>
              </SelectContent>
            </Select>

            {/* 设备过滤 */}
            <Input
              placeholder="搜索设备IP"
              value={deviceFilter}
              onChange={(e) => setDeviceFilter(e.target.value)}
              className="w-40"
            />
          </div>

          <div className="flex items-center gap-2">
            {/* 自动刷新开关 */}
            <Button
              variant={autoRefresh ? 'default' : 'outline'}
              size="sm"
              onClick={() => setAutoRefresh(!autoRefresh)}
              className="flex items-center gap-2"
            >
              <RefreshCw className={`h-4 w-4 ${autoRefresh ? 'animate-spin' : ''}`} />
              自动刷新
            </Button>

            {/* 手动刷新 */}
            <Button
              variant="outline"
              size="sm"
              onClick={loadAnomalies}
              disabled={isLoading}
            >
              <RefreshCw className={`h-4 w-4 ${isLoading ? 'animate-spin' : ''}`} />
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  )

  const renderAnomalyCard = (anomaly: TrafficAnomaly, index: number) => {
    const typeConfig = ANOMALY_TYPE_CONFIG[anomaly.anomaly_type]
    const severityConfig = SEVERITY_CONFIG[anomaly.severity]
    const IconComponent = typeConfig?.icon || AlertTriangle

    return (
      <motion.div
        key={`${anomaly.device_ip}-${anomaly.interface}-${anomaly.timestamp}-${index}`}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: index * 0.05 }}
      >
        <Card className="hover:shadow-md transition-shadow">
          <CardContent className="p-4">
            <div className="flex items-start justify-between mb-3">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${typeConfig?.color || 'bg-gray-100 text-gray-800'}`}>
                  <IconComponent className="h-4 w-4" />
                </div>
                <div>
                  <h4 className="font-medium text-gray-900">{anomaly.device_ip}</h4>
                  <p className="text-sm text-gray-600">{anomaly.interface}</p>
                </div>
              </div>
              <div className="text-right">
                <Badge className={severityConfig.color}>
                  {severityConfig.label}
                </Badge>
                <div className="text-xs text-gray-500 mt-1">
                  {formatDate(anomaly.timestamp, 'datetime')}
                </div>
              </div>
            </div>

            <div className="space-y-2">
              <div className="text-sm text-gray-800">{anomaly.description}</div>

              <div className="flex justify-between text-xs text-gray-600">
                <span>基线值: {formatBytes(anomaly.baseline_value)}</span>
                <span>当前值: {formatBytes(anomaly.current_value)}</span>
              </div>

              <div className="flex justify-between items-center text-xs">
                <span className="text-gray-500">
                  置信度: {(anomaly.confidence * 100).toFixed(1)}%
                </span>
                <Badge variant="outline" className="text-xs">
                  {typeConfig?.label || anomaly.anomaly_type}
                </Badge>
              </div>

              {/* 元数据信息 */}
              {Object.keys(anomaly.metadata).length > 0 && (
                <div className="mt-2 pt-2 border-t">
                  <details className="text-xs">
                    <summary className="cursor-pointer text-gray-600 hover:text-gray-800">
                      详细信息
                    </summary>
                    <div className="mt-1 space-y-1">
                      {Object.entries(anomaly.metadata).map(([key, value]) => (
                        <div key={key} className="flex justify-between">
                          <span className="text-gray-500">{key}:</span>
                          <span className="text-gray-700">{String(value)}</span>
                        </div>
                      ))}
                    </div>
                  </details>
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </motion.div>
    )
  }

  return (
    <div className="space-y-6">
      {/* 统计卡片 */}
      {renderStatsCards()}

      {/* 过滤器 */}
      {renderFilters()}

      {/* 异常列表 */}
      <div>
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold">流量异常详情</h3>
          <div className="flex items-center gap-2 text-sm text-gray-600">
            <Clock className="h-4 w-4" />
            实时更新
          </div>
        </div>

        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <Loading />
          </div>
        ) : filteredAnomalies.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredAnomalies.map((anomaly, index) => renderAnomalyCard(anomaly, index))}
          </div>
        ) : (
          <Card>
            <CardContent className="p-12 text-center">
              <AlertTriangle className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 mb-2">暂无异常</h3>
              <p className="text-gray-600">
                {anomalies.length === 0 
                  ? '当前没有检测到流量异常' 
                  : '当前筛选条件下无匹配的异常'
                }
              </p>
              {anomalies.length === 0 && (
                <Button 
                  onClick={loadAnomalies} 
                  className="mt-4"
                  disabled={isLoading}
                >
                  刷新数据
                </Button>
              )}
            </CardContent>
          </Card>
        )}
      </div>

      {error && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="p-4 bg-red-50 border border-red-200 rounded-lg"
        >
          <div className="flex items-center gap-2 text-red-800">
            <AlertTriangle className="h-4 w-4" />
            <span className="font-medium">加载异常时出错</span>
          </div>
          <p className="text-sm text-red-700 mt-1">{error}</p>
        </motion.div>
      )}
    </div>
  )
}

import React, { useMemo } from 'react'
import { motion } from 'framer-motion'
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ReferenceLine
} from 'recharts'
import {
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  Badge
} from '@/components/atoms'
import { TrafficMetrics } from '../types'
import { formatBytes, formatDate } from '@/utils/formatters'

interface TrafficRealtimeChartProps {
  trafficData: Record<string, TrafficMetrics[]>
  isActive: boolean
}

export const TrafficRealtimeChart: React.FC<TrafficRealtimeChartProps> = ({
  trafficData,
  isActive
}) => {
  // 准备图表数据
  const chartData = useMemo(() => {
    const allMetrics: Array<TrafficMetrics & { device: string }> = []

    Object.entries(trafficData).forEach(([deviceIp, metrics]) => {
      metrics.forEach(metric => {
        allMetrics.push({
          ...metric,
          device: deviceIp
        })
      })
    })

    // 按时间戳排序并限制数据点数量
    return allMetrics
      .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
      .slice(-50) // 只显示最近50个数据点
  }, [trafficData])

  // 按设备和接口分组准备多线图数据
  const lineChartData = useMemo(() => {
    const dataMap = new Map<string, any>()

    chartData.forEach(metric => {
      const timeKey = formatDate(metric.timestamp, 'time')

      if (!dataMap.has(timeKey)) {
        dataMap.set(timeKey, { timestamp: timeKey })
      }

      const data = dataMap.get(timeKey)!
      const deviceInterface = `${metric.device}-${metric.interface}`

      data[`${deviceInterface}_in`] = metric.bytes_in
      data[`${deviceInterface}_out`] = metric.bytes_out
      data[`${deviceInterface}_util`] = metric.bandwidth_utilization
    })

    return Array.from(dataMap.values()).slice(-20) // 显示最近20个时间点
  }, [chartData])

  // 获取所有设备接口的列表，用于生成不同颜色的线条
  const deviceInterfaces = useMemo(() => {
    const interfaces = new Set<string>()
    chartData.forEach(metric => {
      interfaces.add(`${metric.device}-${metric.interface}`)
    })
    return Array.from(interfaces)
  }, [chartData])

  // 颜色配置
  const colors = [
    '#2563eb', '#dc2626', '#059669', '#d97706', 
    '#7c3aed', '#db2777', '#0891b2', '#65a30d'
  ]

  const renderTrafficChart = () => (
    <Card className="col-span-2">
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center gap-2">
            流量趋势
            {isActive && (
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
            )}
          </CardTitle>
          <div className="flex items-center gap-2">
            <Badge variant="outline">
              {Object.keys(trafficData).length} 设备
            </Badge>
            <Badge variant="outline">
              实时监控
            </Badge>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        <div className="h-80">
          {lineChartData.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={lineChartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis 
                  dataKey="timestamp" 
                  tick={{ fontSize: 12 }}
                  interval="preserveStartEnd"
                />
                <YAxis 
                  tick={{ fontSize: 12 }}
                  tickFormatter={(value) => formatBytes(value)}
                />
                <Tooltip
                  formatter={(value: any, name: string) => [
                    formatBytes(value),
                    name.includes('_util') ? '利用率' : 
                    name.includes('_in') ? '入向流量' : '出向流量'
                  ]}
                  labelFormatter={(label) => `时间: ${label}`}
                />
                <Legend />

                {deviceInterfaces.map((deviceInterface, index) => (
                  <React.Fragment key={deviceInterface}>
                    <Line
                      type="monotone"
                      dataKey={`${deviceInterface}_in`}
                      stroke={colors[index % colors.length]}
                      strokeWidth={2}
                      dot={false}
                      name={`${deviceInterface} 入向`}
                      connectNulls={false}
                    />
                    <Line
                      type="monotone"
                      dataKey={`${deviceInterface}_out`}
                      stroke={colors[(index + 1) % colors.length]}
                      strokeWidth={2}
                      strokeDasharray="5 5"
                      dot={false}
                      name={`${deviceInterface} 出向`}
                      connectNulls={false}
                    />
                  </React.Fragment>
                ))}
              </LineChart>
            </ResponsiveContainer>
          ) : (
            <div className="flex items-center justify-center h-full text-gray-500">
              <div className="text-center">
                <div className="text-lg font-medium mb-2">暂无流量数据</div>
                <div className="text-sm">请选择设备并开始监控</div>
              </div>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  )

  const renderUtilizationChart = () => (
    <Card>
      <CardHeader>
        <CardTitle>带宽利用率</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="h-64">
          {lineChartData.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={lineChartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis 
                  dataKey="timestamp" 
                  tick={{ fontSize: 12 }}
                  interval="preserveStartEnd"
                />
                <YAxis 
                  tick={{ fontSize: 12 }}
                  domain={[0, 100]}
                  tickFormatter={(value) => `${value}%`}
                />
                <Tooltip
                  formatter={(value: any) => [`${value}%`, '利用率']}
                  labelFormatter={(label) => `时间: ${label}`}
                />
                <Legend />

                {/* 利用率警戒线 */}
                <ReferenceLine y={80} stroke="#f59e0b" strokeDasharray="5 5" />
                <ReferenceLine y={90} stroke="#dc2626" strokeDasharray="5 5" />

                {deviceInterfaces.map((deviceInterface, index) => (
                  <Line
                    key={deviceInterface}
                    type="monotone"
                    dataKey={`${deviceInterface}_util`}
                    stroke={colors[index % colors.length]}
                    strokeWidth={2}
                    dot={false}
                    name={deviceInterface}
                    connectNulls={false}
                  />
                ))}
              </LineChart>
            </ResponsiveContainer>
          ) : (
            <div className="flex items-center justify-center h-full text-gray-500">
              暂无利用率数据
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  )

  const renderCurrentMetrics = () => {
    if (Object.keys(trafficData).length === 0) {
      return (
        <Card>
          <CardContent className="p-6 text-center text-gray-500">
            暂无实时指标数据
          </CardContent>
        </Card>
      )
    }

    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {Object.entries(trafficData).map(([deviceIp, metrics]) =>
          metrics.map(metric => (
            <motion.div
              key={`${deviceIp}-${metric.interface}`}
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ duration: 0.2 }}
            >
              <Card>
                <CardHeader className="pb-3">
                  <div className="flex items-center justify-between">
                    <CardTitle className="text-sm font-medium">
                      {deviceIp}
                    </CardTitle>
                    <Badge variant="outline" className="text-xs">
                      {metric.interface}
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent className="space-y-3">
                  <div className="grid grid-cols-2 gap-2 text-xs">
                    <div>
                      <div className="text-gray-600">入向</div>
                      <div className="font-medium text-blue-600">
                        {formatBytes(metric.bytes_in)}
                      </div>
                    </div>
                    <div>
                      <div className="text-gray-600">出向</div>
                      <div className="font-medium text-green-600">
                        {formatBytes(metric.bytes_out)}
                      </div>
                    </div>
                  </div>

                  <div className="pt-2 border-t">
                    <div className="flex items-center justify-between text-xs">
                      <span className="text-gray-600">利用率</span>
                      <span className={`font-medium ${
                        metric.bandwidth_utilization > 90 ? 'text-red-600' :
                        metric.bandwidth_utilization > 80 ? 'text-yellow-600' :
                        'text-green-600'
                      }`}>
                        {metric.bandwidth_utilization.toFixed(1)}%
                      </span>
                    </div>

                    {(metric.errors > 0 || metric.discards > 0) && (
                      <div className="mt-1 text-xs text-red-600">
                        错误: {metric.errors}, 丢弃: {metric.discards}
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))
        )}
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* 图表区域 */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        {renderTrafficChart()}
        {renderUtilizationChart()}
      </div>

      {/* 实时指标卡片 */}
      <div>
        <h3 className="text-lg font-semibold mb-4">实时指标</h3>
        {renderCurrentMetrics()}
      </div>
    </div>
  )
}

