'use client'

import { useEffect, useCallback, useRef } from 'react'
import { useRouter } from 'next/navigation'
import React from 'react'

// Web Vitals 监控
interface WebVitals {
  FCP?: number
  LCP?: number
  FID?: number
  CLS?: number
  TTFB?: number
}

// 内存信息接口
interface MemoryInfo {
  usedJSHeapSize: number
  totalJSHeapSize: number
  jsHeapSizeLimit: number
}

export const useWebVitals = (onReport?: (metric: any) => void) => {
  const reportRef = useRef(onReport)
  reportRef.current = onReport

  useEffect(() => {
    const reportVitals = async () => {
      try {
        const { onCLS, onFCP, onLCP, onTTFB, onINP } = await import('web-vitals')

        const handleReport = (metric: any) => {
          console.log('[Web Vitals]', metric)
          reportRef.current?.(metric)
        }

        onCLS(handleReport)
        onFCP(handleReport)
        // onFID 在 web-vitals v5 中已移除，替换为 onINP
        onINP(handleReport)
        onLCP(handleReport)
        onTTFB(handleReport)
      } catch (error) {
        console.warn('Web Vitals not available:', error)
      }
    }

    reportVitals()
  }, [])
}

// 内存使用监控
export const useMemoryMonitor = (intervalMs: number = 30000) => {
  const [memoryInfo, setMemoryInfo] = React.useState<MemoryInfo | null>(null)

  useEffect(() => {
    const checkMemory = () => {
      if ('memory' in performance) {
        const memory = (performance as any).memory
        setMemoryInfo({
          usedJSHeapSize: memory.usedJSHeapSize,
          totalJSHeapSize: memory.totalJSHeapSize,
          jsHeapSizeLimit: memory.jsHeapSizeLimit,
        })
      }
    }

    checkMemory()
    const interval = setInterval(checkMemory, intervalMs)

    return () => clearInterval(interval)
  }, [intervalMs])

  return memoryInfo
}

// 网络状态监控
export const useNetworkStatus = () => {
  const [networkInfo, setNetworkInfo] = React.useState({
    online: navigator.onLine,
    effectiveType: 'unknown',
    downlink: 0,
    rtt: 0,
  })

  useEffect(() => {
    const updateNetworkInfo = () => {
      const connection = (navigator as any).connection || 
                        (navigator as any).mozConnection || 
                        (navigator as any).webkitConnection

      setNetworkInfo({
        online: navigator.onLine,
        effectiveType: connection?.effectiveType || 'unknown',
        downlink: connection?.downlink || 0,
        rtt: connection?.rtt || 0,
      })
    }

    const handleOnline = () => setNetworkInfo(prev => ({ ...prev, online: true }))
    const handleOffline = () => setNetworkInfo(prev => ({ ...prev, online: false }))

    updateNetworkInfo()

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    const connection = (navigator as any).connection
    if (connection) {
      connection.addEventListener('change', updateNetworkInfo)
    }

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
      if (connection) {
        connection.removeEventListener('change', updateNetworkInfo)
      }
    }
  }, [])

  return networkInfo
}

// 页面渲染性能监控
export const useRenderPerformance = (componentName: string) => {
  const renderCountRef = useRef(0)
  const lastRenderTimeRef = useRef(Date.now())

  useEffect(() => {
    renderCountRef.current += 1
    const now = Date.now()
    const timeSinceLastRender = now - lastRenderTimeRef.current
    lastRenderTimeRef.current = now

    if (process.env.NODE_ENV === 'development') {
      console.log(`[Render Performance] ${componentName}:`, {
        renderCount: renderCountRef.current,
        timeSinceLastRender: `${timeSinceLastRender}ms`,
      })
    }
  })

  return {
    renderCount: renderCountRef.current,
  }
}

// 虚拟化列表性能监控
export const useVirtualizationPerformance = () => {
  const [metrics, setMetrics] = React.useState({
    visibleItems: 0,
    totalItems: 0,
    renderTime: 0,
  })

  const measureRenderTime = useCallback((totalItems: number, visibleItems: number) => {
    const startTime = performance.now()

    // 使用 requestIdleCallback 来测量渲染后的性能
    if ('requestIdleCallback' in window) {
      (window as any).requestIdleCallback(() => {
        const endTime = performance.now()
        setMetrics({
          visibleItems,
          totalItems,
          renderTime: endTime - startTime,
        })
      })
    }
  }, [])

  return { metrics, measureRenderTime }
}

// 路由性能监控
export const useRoutePerformance = () => {
  const router = useRouter()
  const [routeMetrics, setRouteMetrics] = React.useState<{
    [key: string]: {
      loadTime: number
      navigateTime: number
    }
  }>({})

  useEffect(() => {
    let navigationStart = 0

    const handleRouteChangeStart = (url: string) => {
      navigationStart = performance.now()
    }

    const handleRouteChangeComplete = (url: string) => {
      if (navigationStart > 0) {
        const loadTime = performance.now() - navigationStart

        setRouteMetrics(prev => ({
          ...prev,
          [url]: {
            ...prev[url],
            loadTime,
            navigateTime: Date.now(),
          }
        }))

        navigationStart = 0
      }
    }

    // 注意：Next.js 13+ App Router 需要使用不同的事件
    // 这里提供一个基础的实现，实际项目中可能需要调整
    const originalPush = router.push
    router.push = (...args) => {
      handleRouteChangeStart(args[0])
      const result = originalPush.apply(router, args)
      // 修复：使用setTimeout而非.finally()，因为router.push返回void
      setTimeout(() => handleRouteChangeComplete(args[0]), 0)
      return result
    }

    return () => {
      // 清理监听器
    }
  }, [router])

  return routeMetrics
}

// 性能监控提供者
interface PerformanceContextType {
  webVitals: WebVitals
  networkStatus: ReturnType<typeof useNetworkStatus>
  memoryInfo: ReturnType<typeof useMemoryMonitor>
}

const PerformanceContext = React.createContext<PerformanceContextType | null>(null)

export const PerformanceProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [webVitals, setWebVitals] = React.useState<WebVitals>({})
  const networkStatus = useNetworkStatus()
  const memoryInfo = useMemoryMonitor()

  useWebVitals((metric) => {
    setWebVitals(prev => ({
      ...prev,
      [metric.name]: metric.value,
    }))
  })

  const value = {
    webVitals,
    networkStatus,
    memoryInfo,
  }

  return (
    <PerformanceContext.Provider value={value}>
      {children}
    </PerformanceContext.Provider>
  )
}

export const usePerformance = () => {
  const context = React.useContext(PerformanceContext)
  if (!context) {
    throw new Error('usePerformance must be used within a PerformanceProvider')
  }
  return context
}

'use client'

/**
 * 认证上下文和Hook
 * 提供全局认证状态管理和用户权限验证
 */

import { createContext, useContext, useEffect, useReducer, useCallback, ReactNode } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'react-hot-toast'
import { api, TokenManager, ApiClientError } from '../api-client'
import {
  AuthState,
  AuthContextType,
  LoginCredentials,
  User,
  UserRole,
  Permission,
  JwtPayload,
} from '../types/auth.types'

// 认证Action类型
type AuthAction =
  | { type: 'SET_LOADING'; payload: boolean }
  | { type: 'LOGIN_SUCCESS'; payload: { user: User } }
  | { type: 'LOGOUT' }
  | { type: 'UPDATE_USER'; payload: Partial<User> }
  | { type: 'SET_ERROR'; payload: string }
  | { type: 'CLEAR_ERROR' }

// 初始状态
const initialState: AuthState = {
  isAuthenticated: false,
  isLoading: true,
  user: null,
  error: null,
}

// 认证状态管理Reducer
function authReducer(state: AuthState, action: AuthAction): AuthState {
  switch (action.type) {
    case 'SET_LOADING':
      return { ...state, isLoading: action.payload }

    case 'LOGIN_SUCCESS':
      return {
        ...state,
        isAuthenticated: true,
        isLoading: false,
        user: action.payload.user,
        error: null,
      }

    case 'LOGOUT':
      return {
        ...state,
        isAuthenticated: false,
        isLoading: false,
        user: null,
        error: null,
      }

    case 'UPDATE_USER':
      return {
        ...state,
        user: state.user ? { ...state.user, ...action.payload } : null,
      }

    case 'SET_ERROR':
      return { ...state, error: action.payload, isLoading: false }

    case 'CLEAR_ERROR':
      return { ...state, error: null }

    default:
      return state
  }
}

// JWT解码工具函数
function decodeJwt(token: string): JwtPayload | null {
  try {
    const base64Payload = token.split('.')[1]
    const payload = JSON.parse(atob(base64Payload))
    return payload as JwtPayload
  } catch {
    return null
  }
}

// JWT是否过期检查
function isTokenExpired(token: string): boolean {
  const payload = decodeJwt(token)
  if (!payload) return true

  const currentTime = Math.floor(Date.now() / 1000)
  return payload.exp < currentTime
}

// 创建认证上下文
const AuthContext = createContext<AuthContextType | undefined>(undefined)

// 认证上下文Provider组件
interface AuthProviderProps {
  children: ReactNode
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [state, dispatch] = useReducer(authReducer, initialState)
  const router = useRouter()

  // 登录函数
  const login = useCallback(async (credentials: LoginCredentials) => {
    try {
      dispatch({ type: 'SET_LOADING', payload: true })
      dispatch({ type: 'CLEAR_ERROR' })

      const response = await api.auth.login(credentials)

      // 保存Token
      TokenManager.setTokens(response.access_token, response.refresh_token)

      // 更新用户状态
      dispatch({ type: 'LOGIN_SUCCESS', payload: { user: response.user } })

      toast.success(`欢迎回来，${response.user.full_name}！`)

      // 跳转到仪表板
      router.push('/dashboard')

    } catch (error) {
      console.error('Login failed:', error)

      let errorMessage = '登录失败，请检查用户名和密码'

      if (error instanceof ApiClientError) {
        if (error.status === 401) {
          errorMessage = '用户名或密码错误'
        } else if (error.status === 403) {
          errorMessage = '账户已被禁用，请联系管理员'
        } else {
          errorMessage = error.message
        }
      }

      dispatch({ type: 'SET_ERROR', payload: errorMessage })
      toast.error(errorMessage)
    }
  }, [router])

  // 登出函数
  const logout = useCallback(async () => {
    try {
      dispatch({ type: 'SET_LOADING', payload: true })

      // 调用后端登出API
      await api.auth.logout()
    } catch (error) {
      console.error('Logout API failed:', error)
    } finally {
      // 清除本地Token
      TokenManager.clearTokens()

      // 更新状态
      dispatch({ type: 'LOGOUT' })

      // 跳转到登录页
      router.push('/login')

      toast.success('已安全退出')
    }
  }, [router])

  // Token刷新函数
  const refreshToken = useCallback(async (): Promise<void> => {
    try {
      const refreshToken = TokenManager.getRefreshToken()
      if (!refreshToken) {
        throw new Error('No refresh token available')
      }

      const response = await api.auth.refresh()

      // 更新Token
      TokenManager.setTokens(response.access_token, response.refresh_token)

    } catch (error) {
      console.error('Token refresh failed:', error)

      // Token刷新失败，强制重新登录
      TokenManager.clearTokens()
      dispatch({ type: 'LOGOUT' })
      router.push('/login')

      throw error // 重新抛出错误，让调用者知道刷新失败
    }
  }, [router])

  // 更新用户信息
  const updateUser = useCallback((userData: Partial<User>) => {
    dispatch({ type: 'UPDATE_USER', payload: userData })
  }, [])

  // 权限检查
  const checkPermission = useCallback((permission: Permission): boolean => {
    if (!state.user) return false
    return state.user.permissions.includes(permission)
  }, [state.user])

  // 角色检查
  const checkRole = useCallback((roles: UserRole | UserRole[]): boolean => {
    if (!state.user) return false
    const roleArray = Array.isArray(roles) ? roles : [roles]
    return roleArray.includes(state.user.role)
  }, [state.user])

  // 清除错误
  const clearError = useCallback(() => {
    dispatch({ type: 'CLEAR_ERROR' })
  }, [])

  // 初始化认证状态
  useEffect(() => {
    const initializeAuth = async () => {
      try {
        const accessToken = TokenManager.getAccessToken()

        if (!accessToken) {
          dispatch({ type: 'SET_LOADING', payload: false })
          return
        }

        // 检查Token是否过期
        if (isTokenExpired(accessToken)) {
          // 尝试刷新Token
          try {
            await refreshToken()
          } catch (error) {
            // 刷新失败，停止初始化
            return
          }
        }

        // 获取用户信息
        const user = await api.auth.profile()
        dispatch({ type: 'LOGIN_SUCCESS', payload: { user } })

      } catch (error) {
        console.error('Auth initialization failed:', error)
        TokenManager.clearTokens()
        dispatch({ type: 'SET_LOADING', payload: false })
      }
    }

    initializeAuth()
  }, [refreshToken])

  // 设置Token自动刷新
  useEffect(() => {
    if (!state.isAuthenticated) return

    const setupTokenRefresh = () => {
      const accessToken = TokenManager.getAccessToken()
      if (!accessToken) return

      const payload = decodeJwt(accessToken)
      if (!payload) return

      // 在Token过期前5分钟刷新
      const refreshTime = (payload.exp - Math.floor(Date.now() / 1000) - 300) * 1000

      if (refreshTime > 0) {
        const timer = setTimeout(async () => {
          await refreshToken()
          setupTokenRefresh() // 递归设置下一次刷新
        }, refreshTime)

        return () => clearTimeout(timer)
      }
    }

    return setupTokenRefresh()
  }, [state.isAuthenticated, refreshToken])

  const contextValue: AuthContextType = {
    ...state,
    login,
    logout,
    refreshToken,
    updateUser,
    checkPermission,
    checkRole,
    clearError,
  }

  return (
    <AuthContext.Provider value={contextValue}>
      {children}
    </AuthContext.Provider>
  )
}

// 认证Hook
export function useAuth(): AuthContextType {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider')
  }
  return context
}

// 权限验证Hook
export function usePermission(permission: Permission): boolean {
  const { checkPermission } = useAuth()
  return checkPermission(permission)
}

// 角色验证Hook
export function useRole(roles: UserRole | UserRole[]): boolean {
  const { checkRole } = useAuth()
  return checkRole(roles)
}

// 需要认证的Hook
export function useRequireAuth() {
  const { isAuthenticated, isLoading } = useAuth()
  const router = useRouter()

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      router.push('/login')
    }
  }, [isAuthenticated, isLoading, router])

  return { isAuthenticated, isLoading }
}

// 访客限制高阶组件（用于登录页等）
export function withGuest<P extends object>(
  WrappedComponent: React.ComponentType<P>
): React.ComponentType<P> {
  return function GuestOnlyComponent(props: P) {
    const { isAuthenticated, isLoading } = useAuth()
    const router = useRouter()

    useEffect(() => {
      if (!isLoading && isAuthenticated) {
        router.push('/dashboard')
      }
    }, [isAuthenticated, isLoading, router])

    // 如果正在加载或已认证，不渲染组件
    if (isLoading || isAuthenticated) {
      return null
    }

    return <WrappedComponent {...props} />
  }
}

/**
 * WebSocket 实时通信管理器
 * 处理实时监控数据和告警推送
 */

import { useEffect } from 'react'
import { io } from 'socket.io-client'
import type { Socket, DisconnectReason } from 'socket.io-client'
import { useAuth } from '@/lib/contexts/auth-context'

// WebSocket事件类型
export enum WebSocketEvents {
  // 连接事件
  CONNECT = 'connect',
  DISCONNECT = 'disconnect',
  ERROR = 'error',
  
  // 监控数据事件
  DEVICE_STATUS_UPDATE = 'device_status_update',
  NETWORK_STATS_UPDATE = 'network_stats_update',
  PERFORMANCE_DATA = 'performance_data',
  TRAFFIC_DATA = 'traffic_data',
  
  // 告警事件
  NEW_ALERT = 'new_alert',
  ALERT_UPDATE = 'alert_update',
  ALERT_RESOLVED = 'alert_resolved',
  
  // 巡检事件
  INSPECTION_START = 'inspection_start',
  INSPECTION_PROGRESS = 'inspection_progress',
  INSPECTION_COMPLETE = 'inspection_complete',
  
  // 系统事件
  SYSTEM_STATUS_UPDATE = 'system_status_update',
  USER_ACTIVITY = 'user_activity',
}

// WebSocket消息类型
interface WebSocketMessage<T = unknown> {
  type: string
  data: T
  timestamp: string
  source?: string
}

// 连接状态
enum ConnectionStatus {
  DISCONNECTED = 'disconnected',
  CONNECTING = 'connecting',
  CONNECTED = 'connected',
  ERROR = 'error',
}

// 事件处理器类型
type EventHandler<T = unknown> = (data: T) => void
type EventHandlerMap = Map<string, EventHandler[]>

// WebSocket管理器类
class WebSocketManager {
  private socket: Socket | null = null
  private status: ConnectionStatus = ConnectionStatus.DISCONNECTED
  private eventHandlers: EventHandlerMap = new Map()
  private reconnectAttempts = 0
  private maxReconnectAttempts = 5
  private reconnectInterval = 5000
  private reconnectTimer: NodeJS.Timeout | null = null

  // 获取WebSocket服务器地址
  private getWebSocketUrl(): string {
    const wsUrl = process.env.NEXT_PUBLIC_WS_URL || 'ws://localhost:8000'
    return `${wsUrl}/api/v1/ws`
  }

  // 连接到WebSocket服务器
  connect(token?: string): Promise<void> {
    return new Promise((resolve, reject) => {
      if (this.socket?.connected) {
        resolve()
        return
      }

      this.status = ConnectionStatus.CONNECTING
      
      try {
        this.socket = io(this.getWebSocketUrl(), {
          auth: token ? { token } : undefined,
          transports: ['websocket'],
          timeout: 10000,
          reconnection: false, // 我们手动处理重连
        })

        // 连接成功
        this.socket.on('connect', () => {
          console.log('WebSocket connected')
          this.status = ConnectionStatus.CONNECTED
          this.reconnectAttempts = 0
          this.clearReconnectTimer()
          this.emit('connection_status', { status: 'connected' })
          resolve()
        })

        // 连接错误
        this.socket.on('connect_error', (error: Error) => {
          console.error('WebSocket connection failed:', error)
          this.status = ConnectionStatus.ERROR
          this.emit('connection_status', { status: 'error', error: error.message })
          reject(error)
        })

        // 连接断开
        this.socket.on('disconnect', (reason: DisconnectReason) => {
          console.warn('WebSocket disconnected:', reason)
          this.status = ConnectionStatus.DISCONNECTED
          this.emit('connection_status', { status: 'disconnected', reason })
          
          // auto reconnect (unless manually disconnected)
          if (reason !== 'client namespace disconnect') {
            this.handleReconnect()
          }
        })

        // 注册所有业务事件处理器
        this.registerEventHandlers()

      } catch (error) {
        console.error('WebSocket initialization failed:', error)
        reject(error)
      }
    })
  }

  // 断开连接
  disconnect(): void {
    this.clearReconnectTimer()
    
    if (this.socket) {
      this.socket.disconnect()
      this.socket = null
    }
    
    this.status = ConnectionStatus.DISCONNECTED
    this.emit('connection_status', { status: 'disconnected' })
  }

  // 注册事件处理器
  on<T = unknown>(event: string, handler: EventHandler<T>): void {
    if (!this.eventHandlers.has(event)) {
      this.eventHandlers.set(event, [])
    }
    this.eventHandlers.get(event)!.push(handler)
  }

  // 移除事件处理器
  off(event: string, handler?: EventHandler): void {
    if (!this.eventHandlers.has(event)) return
    
    if (handler) {
      const handlers = this.eventHandlers.get(event)!
      const index = handlers.indexOf(handler)
      if (index > -1) {
        handlers.splice(index, 1)
      }
    } else {
      this.eventHandlers.set(event, [])
    }
  }

  // send message
  emit(event: string, data?: unknown): void {
    if (this.socket?.connected) {
      this.socket.emit(event, data)
    } else {
      console.warn('WebSocket not connected, cannot send message', event)
    }
  }

  // 获取连接状态
  getStatus(): ConnectionStatus {
    return this.status
  }

  // 是否已连接
  isConnected(): boolean {
    return this.status === ConnectionStatus.CONNECTED && this.socket?.connected === true
  }

  // 注册业务事件处理器
  private registerEventHandlers(): void {
    if (!this.socket) return

    // 设备状态更新
    this.socket.on(WebSocketEvents.DEVICE_STATUS_UPDATE, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.DEVICE_STATUS_UPDATE, data)
    })

    // 网络统计更新
    this.socket.on(WebSocketEvents.NETWORK_STATS_UPDATE, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.NETWORK_STATS_UPDATE, data)
    })

    // 性能数据
    this.socket.on(WebSocketEvents.PERFORMANCE_DATA, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.PERFORMANCE_DATA, data)
    })

    // 流量数据
    this.socket.on(WebSocketEvents.TRAFFIC_DATA, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.TRAFFIC_DATA, data)
    })

    // 新告警
    this.socket.on(WebSocketEvents.NEW_ALERT, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.NEW_ALERT, data)
    })

    // 告警更新
    this.socket.on(WebSocketEvents.ALERT_UPDATE, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.ALERT_UPDATE, data)
    })

    // 告警解决
    this.socket.on(WebSocketEvents.ALERT_RESOLVED, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.ALERT_RESOLVED, data)
    })

    // 巡检开始
    this.socket.on(WebSocketEvents.INSPECTION_START, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.INSPECTION_START, data)
    })

    // 巡检进度
    this.socket.on(WebSocketEvents.INSPECTION_PROGRESS, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.INSPECTION_PROGRESS, data)
    })

    // 巡检完成
    this.socket.on(WebSocketEvents.INSPECTION_COMPLETE, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.INSPECTION_COMPLETE, data)
    })

    // 系统状态更新
    this.socket.on(WebSocketEvents.SYSTEM_STATUS_UPDATE, (data: unknown) => {
      this.dispatchEvent(WebSocketEvents.SYSTEM_STATUS_UPDATE, data)
    })
  }

  // 分发事件到注册的处理器
  private dispatchEvent(event: string, data: unknown): void {
    const handlers = this.eventHandlers.get(event)
    if (handlers) {
      handlers.forEach(handler => {
        try {
          handler(data)
        } catch (error) {
          console.error(`事件处理器错误 (${event}):`, error)
        }
      })
    }
  }

  // 处理重连
  private handleReconnect(): void {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error('WebSocket reconnection attempts exceeded limit, stop retrying')
      return
    }

    this.reconnectAttempts++
    console.log(`WebSocket reconnecting... (${this.reconnectAttempts}/${this.maxReconnectAttempts})`)

    this.reconnectTimer = setTimeout(() => {
      this.connect().catch(() => {
        // Reconnect failed, will retry
      })
    }, this.reconnectInterval)
  }

  // clear reconnect timer
  private clearReconnectTimer(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer)
      this.reconnectTimer = null
    }
  }

  // subscribe device monitoring
  subscribeToDeviceMonitoring(deviceIds?: number[]): void {
    this.emit('subscribe_device_monitoring', { device_ids: deviceIds })
  }

  // 取消subscribe device monitoring
  unsubscribeFromDeviceMonitoring(): void {
    this.emit('unsubscribe_device_monitoring')
  }

  // subscribe alert notifications
  subscribeToAlerts(severity?: string[]): void {
    this.emit('subscribe_alerts', { severity })
  }

  // 取消subscribe alert notifications
  unsubscribeFromAlerts(): void {
    this.emit('unsubscribe_alerts')
  }

  // subscribe inspection tasks
  subscribeToInspectionTasks(): void {
    this.emit('subscribe_inspection_tasks')
  }

  // 取消subscribe inspection tasks
  unsubscribeFromInspectionTasks(): void {
    this.emit('unsubscribe_inspection_tasks')
  }

  // send heartbeat
  sendHeartbeat(): void {
    this.emit('heartbeat', { timestamp: Date.now() })
  }
}

// 创建全局WebSocket管理器实例
export const wsManager = new WebSocketManager()

// WebSocket Hook
export function useWebSocket() {
  return {
    connect: (token?: string) => wsManager.connect(token),
    disconnect: () => wsManager.disconnect(),
    on: <T = unknown>(event: string, handler: EventHandler<T>) => wsManager.on(event, handler),
    off: (event: string, handler?: EventHandler) => wsManager.off(event, handler),
    emit: (event: string, data?: unknown) => wsManager.emit(event, data),
    isConnected: () => wsManager.isConnected(),
    getStatus: () => wsManager.getStatus(),
    subscribeToDeviceMonitoring: (deviceIds?: number[]) => wsManager.subscribeToDeviceMonitoring(deviceIds),
    unsubscribeFromDeviceMonitoring: () => wsManager.unsubscribeFromDeviceMonitoring(),
    subscribeToAlerts: (severity?: string[]) => wsManager.subscribeToAlerts(severity),
    unsubscribeFromAlerts: () => wsManager.unsubscribeFromAlerts(),
    subscribeToInspectionTasks: () => wsManager.subscribeToInspectionTasks(),
    unsubscribeFromInspectionTasks: () => wsManager.unsubscribeFromInspectionTasks(),
  }
}

// 便捷Hook：监听特定事件
export function useWebSocketEvent<T = unknown>(event: string, handler: EventHandler<T>) {
  const { on, off } = useWebSocket()
  
  // 使用useEffect来管理事件监听器的生命周期
  useEffect(() => {
    on(event, handler)
    
    return () => {
      off(event, handler)
    }
  }, [event, handler, on, off])
}

// 用于React组件的Hook
import { useEffect, useCallback } from 'react'
import { useAuth } from '@/lib/contexts/auth-context'

export function useWebSocketConnection() {
  const { isAuthenticated, user } = useAuth()
  const ws = useWebSocket()

  // 自动连接/断开
  useEffect(() => {
    if (isAuthenticated && user) {
      // 使用用户的access token连接WebSocket
      const token = typeof window !== 'undefined' ? localStorage.getItem('access_token') : null
      ws.connect(token || undefined).catch(console.error)
    } else {
      ws.disconnect()
    }

    // 组件卸载时断开连接
    return () => {
      ws.disconnect()
    }
  }, [isAuthenticated, user, ws])

  return ws
}

export default wsManager

// 代码分割配置工具
export const createChunkName = (featureName: string, componentName?: string) => {
  return componentName ? `${featureName}-${componentName}` : featureName
}

// 动态导入工具
export const dynamicImport = <T = unknown>(
  importFn: () => Promise<{ default: T }>,
  options?: {
    chunkName?: string
    retries?: number
    fallback?: T
  }
): Promise<T> => {
  const { retries = 3, fallback } = options || {}

  let attempt = 0

  const tryImport = async (): Promise<T> => {
    try {
      const loadedModule = await importFn()
      return loadedModule.default
    } catch (error) {
      attempt++

      if (attempt <= retries) {
        // 指数退避重试
        const delay = Math.pow(2, attempt - 1) * 1000
        await new Promise(resolve => setTimeout(resolve, delay))
        return tryImport()
      }

      if (typeof fallback !== 'undefined') {
        console.warn('Dynamic import failed, using fallback:', error)
        return fallback
      }

      throw error
    }
  }

  return tryImport()
}

// 特性检测和polyfill加载
export const loadPolyfillIfNeeded = async (
  featureName: string,
  polyfillImport: () => Promise<unknown>
) => {
  // 检查特性是否已存在
  const featureChecks: Record<string, () => boolean> = {
    'IntersectionObserver': () => 'IntersectionObserver' in window,
    'ResizeObserver': () => 'ResizeObserver' in window,
    'requestIdleCallback': () => 'requestIdleCallback' in window,
    'fetch': () => 'fetch' in window,
    'AbortController': () => 'AbortController' in window,
    'WebGL': () => {
      try {
        const canvas = document.createElement('canvas')
        return !!(canvas.getContext('webgl') || canvas.getContext('experimental-webgl'))
      } catch {
        return false
      }
    }
  }

  const check = featureChecks[featureName]
  if (check && !check()) {
    try {
      await polyfillImport()
      console.log(`Polyfill loaded for: ${featureName}`)
    } catch (error) {
      console.warn(`Failed to load polyfill for ${featureName}:`, error)
    }
  }
}

// 模块缓存管理
class ModuleCache {
  private cache = new Map<string, Promise<unknown>>()

  get<T>(key: string, importFn: () => Promise<T>): Promise<T> {
    if (this.cache.has(key)) {
      return this.cache.get(key)! as Promise<T>
    }

    const promise = importFn()
    this.cache.set(key, promise)

    return promise
  }

  clear(key?: string) {
    if (key) {
      this.cache.delete(key)
    } else {
      this.cache.clear()
    }
  }

  size() {
    return this.cache.size
  }
}

export const moduleCache = new ModuleCache()

// 预加载策略
export const preloadStrategy = {
  // 鼠标悬停预加载
  onHover: (importFn: () => Promise<unknown>, delay: number = 100) => {
    let timeoutId: NodeJS.Timeout | null = null

    return {
      onMouseEnter: () => {
        timeoutId = setTimeout(() => {
          importFn().catch(error => {
            console.warn('Preload on hover failed:', error)
          })
        }, delay)
      },
      onMouseLeave: () => {
        if (timeoutId) {
          clearTimeout(timeoutId)
          timeoutId = null
        }
      }
    }
  },

  // 可见区域预加载
  onVisible: (
    importFn: () => Promise<unknown>,
    options?: IntersectionObserverInit
  ) => {
    return (element: HTMLElement | null) => {
      if (!element || !('IntersectionObserver' in window)) return

      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              importFn().catch(error => {
                console.warn('Preload on visible failed:', error)
              })
              observer.unobserve(entry.target)
            }
          })
        },
        { threshold: 0.1, ...options }
      )

      observer.observe(element)

      return () => observer.disconnect()
    }
  },

  // 空闲时预加载
  onIdle: (importFn: () => Promise<unknown>, timeout: number = 2000) => {
    const preload = () => {
      importFn().catch(error => {
        console.warn('Preload on idle failed:', error)
      })
    }

    const idleWindow = window as Window & {
      requestIdleCallback?: (callback: IdleRequestCallback, options?: IdleRequestOptions) => number
    }

    if (idleWindow.requestIdleCallback) {
      idleWindow.requestIdleCallback(preload, { timeout })
    } else {
      setTimeout(preload, 1)
    }
  }
}

// Bundle 分析工具
export const bundleAnalyzer = {
  // 记录模块加载时间
  logModuleLoadTime: (moduleName: string, startTime: number) => {
    const loadTime = performance.now() - startTime
    console.log(`[Bundle] ${moduleName} loaded in ${loadTime.toFixed(2)}ms`)

    // 发送到分析服务（如果需要）
    if (process.env.NODE_ENV === 'production' && window.gtag) {
      window.gtag('event', 'module_load_time', {
        event_category: 'performance',
        event_label: moduleName,
        value: Math.round(loadTime)
      })
    }
  },

  // 检查chunk大小
  checkChunkSize: (chunkName: string, threshold: number = 244 * 1024) => {
    // 这个函数在生产环境中需要配合webpack插件使用
    if (process.env.NODE_ENV === 'development') {
      console.log(`[Bundle] Checking chunk size for: ${chunkName}`)
    }
  }
}

// 关键资源提示
export const resourceHints = {
  // 预连接到外部域名
  preconnect: (domains: string[]) => {
    domains.forEach(domain => {
      const link = document.createElement('link')
      link.rel = 'preconnect'
      link.href = domain
      document.head.appendChild(link)
    })
  },

  // DNS预解析
  dnsPrefetch: (domains: string[]) => {
    domains.forEach(domain => {
      const link = document.createElement('link')
      link.rel = 'dns-prefetch'
      link.href = domain
      document.head.appendChild(link)
    })
  },

  // 预加载关键资源
  preload: (resources: Array<{ href: string; as: string; type?: string }>) => {
    resources.forEach(({ href, as, type }) => {
      const link = document.createElement('link')
      link.rel = 'preload'
      link.href = href
      link.as = as
      if (type) link.type = type
      document.head.appendChild(link)
    })
  }
}
